// The service's base URL, as the widget's `service-url` attribute (docs/08-widget.md §2) and the
// headless client's `serviceUrl` option take it. Total: an invalid value gives `null`, never throws.
//
// A client module (task 44, the headless client): it imports only other client modules and
// zod-free values of `@askfolio/shared`, and touches no DOM at import time.

/** Removes trailing slashes without a regular expression (no backtracking on long inputs). */
function trimTrailingSlashes(value: string): string {
  let end = value.length;
  while (end > 0 && value.charCodeAt(end - 1) === 0x2f) end -= 1;
  return value.slice(0, end);
}

/**
 * An absolute `http(s)` URL, without credentials, query or fragment, returned without trailing
 * slash; `null` when absent or invalid (the element then renders nothing).
 */
export function readServiceUrl(value: string | null): string | null {
  if (value === null || value.trim() === "") return null;
  let url: URL;
  try {
    url = new URL(value.trim());
  } catch {
    return null;
  }
  if (url.protocol !== "https:" && url.protocol !== "http:") return null;
  if (url.username !== "" || url.password !== "" || url.search !== "" || url.hash !== "") {
    return null;
  }
  return trimTrailingSlashes(`${url.origin}${url.pathname}`);
}
