// The one automatic resend of a chat or job-offer request (docs/03-api-contract.md §11,
// docs/08-widget.md §5 items 5 and 6): after `401 unauthorized`, a new session, then the request
// once more without its conversation (a conversation belongs to the session that created it);
// after `404 not_found` on a conversation, the request once more without it. Anything else, or a
// failure of the resend itself, is not resent.
//
// A client module (task 44, the headless client): it imports only other client modules and
// zod-free values of `@askfolio/shared`, and touches no DOM at import time.
import type { Failure } from "./stream.js";

/**
 * What to do before the one resend: create a new session and drop the conversation
 * (`new_session`), only drop the conversation (`drop_conversation`), or not resend (`null`).
 */
export type ResendPlan = "new_session" | "drop_conversation" | null;

/**
 * The resend for `failure` of a request that carried a conversation (`hasConversation`) or not,
 * and that was or was not itself a resend (`alreadyResent`). A job offer has no conversation, so
 * it is resent after `401` only.
 */
export function resendPlan(
  failure: Failure,
  context: { hasConversation: boolean; alreadyResent: boolean },
): ResendPlan {
  if (failure.kind !== "http" || context.alreadyResent) return null;
  if (failure.code === "unauthorized") return "new_session";
  return failure.code === "not_found" && context.hasConversation ? "drop_conversation" : null;
}
