// `GET /v1/health` (docs/03-api-contract.md §9) and its mapping to a widget state
// (docs/08-widget.md §5): network failure, timeout, non-200, an unusable body or `snapshot: null`
// → `unavailable`; `budget: "exhausted"` → `budget-exhausted`; otherwise `idle`. The `state` field
// (degraded or not) is ignored. Never throws and never retries.
//
// A client module (task 44, the headless client): it imports only other client modules and
// zod-free values of `@askfolio/shared`, and touches no DOM at import time.
import { CLIENT_HEALTH_TIMEOUT_MS, type HealthResponse } from "@askfolio/shared";
import { isObject } from "./stream.js";

export type HealthState = "idle" | "unavailable" | "budget-exhausted";

/** Why health says `unavailable`, for diagnostics only; the widget ignores it. */
export type HealthReason = "network" | "timeout" | "http_status" | "bad_response" | "no_snapshot";

export type HealthResult = {
  state: HealthState;
  /** `turnstileSiteKey` of the response, `null` when there is no usable response. */
  siteKey: string | null;
  /** `Date.now()` when the result arrived. */
  at: number;
  /** With `unavailable`: why; otherwise `null`. */
  reason: HealthReason | null;
};

/** Whether `body` carries the fields of `HealthResponse` the widget reads. */
function isHealthResponse(body: unknown): body is HealthResponse {
  if (!isObject(body)) return false;
  const snapshot = body.snapshot;
  return (
    (snapshot === null || (isObject(snapshot) && typeof snapshot.version === "string")) &&
    (body.budget === "ok" || body.budget === "exhausted") &&
    typeof body.turnstileSiteKey === "string" &&
    body.turnstileSiteKey !== ""
  );
}

export function healthState(body: HealthResponse): HealthState {
  if (body.snapshot === null) return "unavailable";
  return body.budget === "exhausted" ? "budget-exhausted" : "idle";
}

/**
 * Calls health with a `CLIENT_HEALTH_TIMEOUT_MS` timeout (body included). Resolves to `null` when
 * `signal` aborted the call (disconnect), to a result otherwise. `fetcher` replaces the global
 * `fetch`, which is otherwise looked up when the request is made.
 */
export async function checkHealth(
  serviceUrl: string,
  signal: AbortSignal,
  timeoutMs: number = CLIENT_HEALTH_TIMEOUT_MS,
  fetcher?: typeof fetch,
): Promise<HealthResult | null> {
  const controller = new AbortController();
  let timedOut = false;
  const abort = (): void => controller.abort();
  signal.addEventListener("abort", abort, { once: true });
  const timer = setTimeout(() => {
    timedOut = true;
    abort();
  }, timeoutMs);
  const unavailable = (reason: HealthReason): HealthResult | null =>
    signal.aborted
      ? null
      : {
          state: "unavailable",
          siteKey: null,
          at: Date.now(),
          reason: timedOut ? "timeout" : reason,
        };
  const init: RequestInit = {
    method: "GET",
    signal: controller.signal,
    credentials: "omit",
    cache: "no-store",
  };
  const url = `${serviceUrl}/v1/health`;
  let response: Response | undefined;
  try {
    // Called as a plain function: see `post` in stream.ts.
    response = await (fetcher === undefined ? fetch(url, init) : fetcher(url, init));
    if (response.status !== 200) return unavailable("http_status");
    const body: unknown = await response.json();
    if (signal.aborted) return null;
    if (!isHealthResponse(body)) return unavailable("bad_response");
    const state = healthState(body);
    const reason = state === "unavailable" ? "no_snapshot" : null;
    return { state, siteKey: body.turnstileSiteKey, at: Date.now(), reason };
  } catch {
    return unavailable(response === undefined ? "network" : "bad_response");
  } finally {
    clearTimeout(timer);
    signal.removeEventListener("abort", abort);
  }
}
