// The headless client's stored session (D22, docs/03-api-contract.md §4.2): one entry per service,
// `askfolio:session:<serviceUrl>`, in `sessionStorage` by default or in a store the integrator
// gives, holding only what a page load needs to continue: the session token, its expiry, the
// limits, the conversation id and its scope. Never `localStorage`, never a cookie.
//
// Every access is guarded. A storage that is absent, throws on a read or refuses a write switches
// this object to memory for the rest of the page's life, after one attempt to remove the entry so
// that a stale one does not come back on the next page; the client then keeps its state in its own
// fields. An entry is checked as strictly as a session response is (`isSessionResponse` in
// session.ts), plus its expiry: one that is malformed, of an unknown version, or that expires
// within `CLIENT_SESSION_RESTORE_MARGIN_MS` is removed, never restored. The widget does not use
// this module: it keeps its token in memory.
//
// A client module (task 44, the headless client): it imports only other client modules and
// zod-free values of `@askfolio/shared`, and touches no DOM at import time.
import {
  CLIENT_SESSION_RESTORE_MARGIN_MS,
  isScope,
  type Scope,
  SESSION_TOKEN_MAX_CHARS,
  type SessionLimits,
} from "@askfolio/shared";
import { DEFAULT_LIMITS, type SessionSnapshot } from "./session.js";
import { isObject } from "./stream.js";

/** The subset of the Web Storage API used here. */
export type KeyValueStore = {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
};

/** Where the entry is kept: `sessionStorage`, nowhere (memory), or the integrator's store. */
export type StorageChoice = "session" | "memory" | KeyValueStore;

/** What a page load continues with: the session, and the conversation when there is one. */
export type StoredSession = SessionSnapshot & {
  conversation: { id: string; scope: Scope } | null;
};

/** Version of the stored entry; an entry of another version is removed. */
export const STORAGE_VERSION = 1;

/** A conversation id is short (`c_` and 22 characters); anything longer is not one. */
const CONVERSATION_ID_MAX_CHARS = 64;

const LIMIT_KEYS = Object.keys(DEFAULT_LIMITS) as (keyof SessionLimits)[];

/** The key of the entry for a service URL as `readServiceUrl` returns it. */
export function storageKey(serviceUrl: string): string {
  return `askfolio:session:${serviceUrl}`;
}

function isLimits(value: unknown): value is SessionLimits {
  return (
    isObject(value) &&
    LIMIT_KEYS.every((key) => {
      const limit = value[key];
      return typeof limit === "number" && Number.isInteger(limit) && limit >= 0;
    })
  );
}

function isConversation(value: unknown): value is { id: string; scope: Scope } {
  return (
    isObject(value) &&
    typeof value.id === "string" &&
    value.id !== "" &&
    value.id.length <= CONVERSATION_ID_MAX_CHARS &&
    isScope(value.scope)
  );
}

/**
 * The stored session in `text`, or `null` when it is malformed, of another version, or expires
 * within the restore margin of `now`.
 */
export function parseStoredSession(text: string, now: number): StoredSession | null {
  let entry: unknown;
  try {
    entry = JSON.parse(text);
  } catch {
    return null;
  }
  if (!isObject(entry) || entry.v !== STORAGE_VERSION) return null;
  const { token, expiresAt, limits, conversation } = entry;
  if (
    typeof token !== "string" ||
    token.length === 0 ||
    token.length > SESSION_TOKEN_MAX_CHARS ||
    typeof expiresAt !== "string" ||
    !isLimits(limits) ||
    !(conversation === null || isConversation(conversation))
  ) {
    return null;
  }
  const expiry = Date.parse(expiresAt);
  if (Number.isNaN(expiry) || expiry - now < CLIENT_SESSION_RESTORE_MARGIN_MS) return null;
  const kept = Object.fromEntries(LIMIT_KEYS.map((key) => [key, limits[key]])) as SessionLimits;
  return {
    token,
    expiresAt,
    limits: kept,
    conversation: conversation === null ? null : { id: conversation.id, scope: conversation.scope },
  };
}

/**
 * Reads, writes and removes the entry of one service. Every method is total: none throws, and a
 * failing storage turns this object into a no-op (memory mode).
 */
export class SessionPersistence {
  readonly #key: string;
  readonly #choice: StorageChoice;
  /** The store in use; `null` in memory mode, `undefined` until first needed. */
  #store: KeyValueStore | null | undefined;

  constructor(choice: StorageChoice, serviceUrl: string) {
    this.#choice = choice;
    this.#key = storageKey(serviceUrl);
  }

  /** Whether the entry lives in memory only, by choice or after a storage failure. */
  get memory(): boolean {
    return this.#resolve() === null;
  }

  /** The stored session, or `null`; an unusable entry is removed. */
  read(now: number): StoredSession | null {
    const store = this.#resolve();
    if (store === null) return null;
    let text: string | null;
    try {
      text = store.getItem(this.#key);
    } catch {
      this.#fail(store);
      return null;
    }
    if (typeof text !== "string") return null;
    const entry = parseStoredSession(text, now);
    if (entry === null) this.remove();
    return entry;
  }

  /** Stores `entry`; a refused write switches to memory. */
  write(entry: StoredSession): void {
    const store = this.#resolve();
    if (store === null) return;
    const value = JSON.stringify({
      v: STORAGE_VERSION,
      token: entry.token,
      expiresAt: entry.expiresAt,
      limits: entry.limits,
      conversation: entry.conversation,
    });
    try {
      store.setItem(this.#key, value);
    } catch {
      this.#fail(store);
    }
  }

  /** Removes the entry; a failing removal switches to memory. */
  remove(): void {
    const store = this.#resolve();
    if (store === null) return;
    try {
      store.removeItem(this.#key);
    } catch {
      this.#store = null;
    }
  }

  /** The store, looked up once: `sessionStorage` may be absent, or throw when read (a sandbox). */
  #resolve(): KeyValueStore | null {
    if (this.#store !== undefined) return this.#store;
    const choice = this.#choice;
    let store: unknown = null;
    if (choice === "session") {
      try {
        store = (globalThis as { sessionStorage?: unknown }).sessionStorage ?? null;
      } catch {
        store = null;
      }
    } else if (choice !== "memory") {
      store = choice;
    }
    this.#store = isStore(store) ? store : null;
    return this.#store;
  }

  /** Switches to memory after a failure, with one attempt to remove the entry. */
  #fail(store: KeyValueStore): void {
    this.#store = null;
    try {
      store.removeItem(this.#key);
    } catch {
      // Memory mode already; nothing else to do.
    }
  }
}

function isStore(value: unknown): value is KeyValueStore {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Partial<Record<keyof KeyValueStore, unknown>>;
  try {
    return (
      typeof candidate.getItem === "function" &&
      typeof candidate.setItem === "function" &&
      typeof candidate.removeItem === "function"
    );
  } catch {
    return false;
  }
}
