// Normalisation of text received from visitors (docs/03-api-contract.md §1) and of job-offer
// text, pasted or extracted (docs/09-job-offer-analysis.md §1). Character limits count Unicode
// code points after normalisation (`codePointLength`).

const LONE_SURROGATE = /[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/g;
/** C0 controls, DEL and C1 controls (`\p{Cc}`), except line feed and tab. */
const CONTROL_EXCEPT_LF_TAB = /(?![\n\t])\p{Cc}/gu;
/** Zero-width space, non-joiner, joiner, word joiner and byte order mark. */
const ZERO_WIDTH = /\u200B|\u200C|\u200D|\u2060|\uFEFF/g;
/** Runs of two or more space characters (tab excluded: it is kept as is). */
const SPACE_RUN = /[ \u00A0\u1680\u2000-\u200A\u202F\u205F\u3000]{2,}/g;
const NEWLINE_RUN = /\n{3,}/g;

/**
 * Same result as `String.prototype.toWellFormed()` (ES2024, not in this package's `lib`): lone
 * surrogates become U+FFFD. Every string sent to the state store goes through it (docs/05 §8).
 */
export function toWellFormed(text: string): string {
  return text.replace(LONE_SURROGATE, "\uFFFD");
}

/**
 * Visitor text: lone surrogates replaced with U+FFFD, Unicode NFC, control characters removed
 * except `\n` and `\t`, leading and trailing whitespace trimmed.
 */
export function normaliseVisitorText(text: string): string {
  return toWellFormed(text).normalize("NFC").replace(CONTROL_EXCEPT_LF_TAB, "").trim();
}

/**
 * Job-offer text: the visitor-text rules, plus zero-width characters removed, runs of spaces
 * collapsed to one space and more than two consecutive newlines collapsed to two.
 */
export function normaliseOfferText(text: string): string {
  return toWellFormed(text)
    .normalize("NFC")
    .replace(CONTROL_EXCEPT_LF_TAB, "")
    .replace(ZERO_WIDTH, "")
    .replace(SPACE_RUN, " ")
    .replace(NEWLINE_RUN, "\n\n")
    .trim();
}

/** Number of Unicode code points (a surrogate pair counts once). */
export function codePointLength(text: string): number {
  let length = 0;
  for (const _ of text) length += 1;
  return length;
}
