// Limit defaults: the single source of every number in docs/10-configuration-reference.md, and
// the named constants for the fixed values that have no environment variable (S27). Every
// ceiling used by a package comes from here (AGENTS.md rule 11).

/** Range and default of one numeric `ASKFOLIO_*` variable (docs/10, "Type" and "Default"). */
export type LimitSpec = {
  readonly default: number;
  readonly min: number;
  /** Inclusive upper bound; `Number.MAX_SAFE_INTEGER` when the table gives only a lower bound. */
  readonly max: number;
  /** `true` for `int`, `false` for `decimal`. */
  readonly integer: boolean;
};

const UNBOUNDED = Number.MAX_SAFE_INTEGER;

function int(defaultValue: number, min: number, max: number = UNBOUNDED): LimitSpec {
  return Object.freeze({ default: defaultValue, min, max, integer: true });
}

function decimal(defaultValue: number, min: number, max: number = UNBOUNDED): LimitSpec {
  return Object.freeze({ default: defaultValue, min, max, integer: false });
}

