// Chunked replay of degraded mode (docs/05 §8.5 "Recovery"): recovery sends what memory recorded
// as a sequence of `spend.replayDegraded` calls, each one within the ceilings below, which keep a
// margin of at least half under the per-mutation limits of Convex.

/** Convex: elements of one array argument. */
export const CONVEX_MAX_ARRAY_ELEMENTS = 8192;
/** Convex: documents one mutation writes (every insert and patch counts). */
export const CONVEX_MAX_DOCUMENTS_WRITTEN = 16_000;
/** Convex: index ranges one mutation reads (every `db.get` and `db.query`). */
export const CONVEX_MAX_INDEX_RANGES_READ = 4096;
/** Elements of each array of one replay call (ledger rows, counters, revoked sessions). */
export const REPLAY_CHUNK_MAX_ELEMENTS = 2000;
/** Documents one replay call may write, each element counted at its worst case. */
export const REPLAY_CHUNK_MAX_WRITES = 4000;
/** Index ranges one replay call may read, each element counted at its worst case. */
export const REPLAY_CHUNK_MAX_READS = 2048;
/** Worst-case writes and index-range reads of `spend.replayDegraded` per element and per call. */
export const REPLAY_COSTS = Object.freeze({
  /** A ledger row: its insert, the day's `daily_spend` read, then inserted or patched. */
  spend: Object.freeze({ writes: 2, reads: 1 }),
  /** A counter: a placeholder session (read, insert, get), the counter (read twice, written) and the `sessions` field it mirrors (read, patch). */
  counter: Object.freeze({ writes: 3, reads: 5 }),
  /** A revocation: a placeholder session (read, insert, get), then the `revoked` patch. */
  revocation: Object.freeze({ writes: 2, reads: 2 }),
  /** The call itself: the day's budget state it returns. */
  call: Object.freeze({ writes: 0, reads: 1 }),
});
/**
 * Deadline of one replay call, used instead of `ASKFOLIO_STATE_TIMEOUT_MS` when that is shorter:
 * a full chunk is thousands of database operations and hundreds of kilobytes.
 */
export const STATE_REPLAY_TIMEOUT_MS = 20_000;
/**
 * A replay call that timed out halves the chunk ceilings for the next probe, at most this many
 * times (1/64: still room for one element of each kind at its worst case); a probe whose every
 * chunk committed restores them.
 */
export const REPLAY_CHUNK_MAX_HALVINGS = 6;

