// Client checks and request body of a job offer (docs/09-job-offer-analysis.md §1, §3,
// docs/03-api-contract.md §7, docs/08-widget.md §7). The checks mirror the service's with the
// session limits (the shared defaults before a session exists, S42): a refused input is reported
// as a code with the limit it broke, and nothing is sent; the widget turns the code into its inline
// error. The PDF goes to the service only, as one `file` part named `offer.pdf`; nothing here
// stores it, reads more than its first bytes, or puts it or the text in an event or a log (rule 9).
//
// A client module (task 44, the headless client): it imports only other client modules and
// zod-free values of `@askfolio/shared`, and touches no DOM at import time.
import { codePointLength, normaliseOfferText, type SessionLimits } from "@askfolio/shared";

export const PDF_TYPE = "application/pdf";
/** The service looks for the signature in the first 1024 bytes (docs/09 §2). */
const SIGNATURE_WINDOW = 1024;
/** File name of the part: the visitor's own file name never leaves the browser. */
const PART_FILE_NAME = "offer.pdf";

/**
 * Why a job offer was refused before sending, with the limit it broke: the size limit in bytes
 * for a PDF, the length limit in code points for a text, none for a file that is not a PDF.
 */
export type OfferProblem =
  | { code: "offer_pdf_type"; limit: null }
  | { code: "offer_pdf_too_large"; limit: number }
  | { code: "offer_text_too_short"; limit: number }
  | { code: "offer_text_too_long"; limit: number };

async function hasPdfSignature(file: Blob): Promise<boolean> {
  try {
    const head = new Uint8Array(await file.slice(0, SIGNATURE_WINDOW).arrayBuffer());
    return String.fromCharCode(...head).includes("%PDF-");
  } catch {
    return false;
  }
}

/**
 * Checks a chosen file: declared type (a `.pdf` name when the browser gives no type; a `Blob` has
 * no name), size, and the `%PDF-` signature. Resolves to the problem, or `null` when the file can
 * be sent.
 */
export async function checkPdf(file: Blob, limits: SessionLimits): Promise<OfferProblem | null> {
  const name = (file as Partial<File>).name;
  const declared =
    file.type === PDF_TYPE ||
    (file.type === "" && typeof name === "string" && /\.pdf$/i.test(name));
  if (!declared) return { code: "offer_pdf_type", limit: null };
  if (file.size > limits.jobOfferMaxPdfBytes) {
    return { code: "offer_pdf_too_large", limit: limits.jobOfferMaxPdfBytes };
  }
  return (await hasPdfSignature(file)) ? null : { code: "offer_pdf_type", limit: null };
}

/** Length of the pasted text as the service counts it: code points after normalisation. */
export function offerLength(text: string): number {
  return codePointLength(normaliseOfferText(text));
}

/** The problem of a pasted text of `length` code points, or `null`. */
export function checkOfferText(length: number, limits: SessionLimits): OfferProblem | null {
  if (length > limits.jobOfferMaxTextChars) {
    return { code: "offer_text_too_long", limit: limits.jobOfferMaxTextChars };
  }
  return length < limits.jobOfferMinTextChars
    ? { code: "offer_text_too_short", limit: limits.jobOfferMinTextChars }
    : null;
}

/** What a submission sends: the PDF, or the normalised text. */
export type OfferInput = { kind: "pdf"; file: Blob } | { kind: "text"; text: string };

/** The body of `POST /v1/job-offer`: JSON `{ text }`, or a form with exactly one `file` part. */
export function offerBody(input: OfferInput): string | FormData {
  if (input.kind === "text") return JSON.stringify({ text: input.text });
  const form = new FormData();
  form.append("file", new File([input.file], PART_FILE_NAME, { type: PDF_TYPE }));
  return form;
}
