// HTTP and SSE client (docs/03-api-contract.md §2, §8, §11). Requests use `fetch` (the global
// one, or the caller's); an answer is read with a `ReadableStream` reader and the `SseParser` of
// `@askfolio/shared`, never with `EventSource` (it cannot send a POST body or an `Authorization`
// header). There is no reconnection and no automatic retry: a stream silent for
// `CLIENT_STREAM_STALL_MS` (keepalives included), ending without `done` or carrying an invalid
// event is dropped, and the caller shows it.
//
// A client module (task 44, the headless client): it imports only other client modules and
// zod-free values of `@askfolio/shared`, and touches no DOM at import time.
//
// Payloads are checked here with type guards over the shared types instead of the shared Zod
// schemas: the schemas would bring zod into the bundle, about 35 KB gzipped, as much as the
// whole widget, to repeat the service's validation (docs/08-widget.md §12, whose only runtime
// dependencies are a markdown parser and a sanitiser; S84 (a)). The guards check what the widget
// reads; unknown fields are ignored.
import {
  CLIENT_STREAM_STALL_MS,
  DONE_STATUSES,
  ERROR_CODES,
  type ErrorCode,
  type JobOfferReport,
  MESSAGE_MODES,
  MESSAGE_VALIDATIONS,
  PROGRESS_STAGES,
  type RawSseEvent,
  REQUIREMENT_IMPORTANCES,
  REQUIREMENT_MATCHES,
  SOURCE_KINDS,
  SOURCES_MAX_FILES,
  type SourceFile,
  SSE_EVENT_NAMES,
  type SseEvent,
  SseParser,
} from "@askfolio/shared";

/** Why a request did not produce a usable response. */
export type Failure =
  | { kind: "network" }
  | { kind: "http"; status: number; code: ErrorCode; retryAfter: number | null };

export type Outcome<T> = { ok: true; value: T } | { ok: false; failure: Failure } | "aborted";

type Json = Record<string, unknown>;

export function isObject(value: unknown): value is Json {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isErrorCode(value: unknown): value is ErrorCode {
  return typeof value === "string" && (ERROR_CODES as readonly string[]).includes(value);
}

/** `Retry-After` in seconds (delta-seconds or an HTTP date), or `null`. */
export function parseRetryAfter(header: string | null, now: number): number | null {
  if (header === null) return null;
  const trimmed = header.trim();
  if (/^\d{1,10}$/.test(trimmed)) return Number(trimmed);
  const date = Date.parse(trimmed);
  if (Number.isNaN(date)) return null;
  return Math.max(0, Math.ceil((date - now) / 1000));
}

/** Code of an unparseable error body, from the status alone. */
function codeFromStatus(status: number): ErrorCode {
  switch (status) {
    case 401:
      return "unauthorized";
    case 404:
      return "not_found";
    case 409:
      return "conversation_limit";
    case 413:
      return "payload_too_large";
    case 429:
      return "rate_limited";
    case 503:
      return "service_unavailable";
    default:
      return "internal_error";
  }
}

/** Reads the `ErrorBody` of a non-success response; never throws. */
export async function readFailure(response: Response): Promise<Failure> {
  let code = codeFromStatus(response.status);
  try {
    const body: unknown = await response.json();
    if (isObject(body) && isObject(body.error) && isErrorCode(body.error.code)) {
      code = body.error.code;
    }
  } catch {
    // Not JSON: the status decides.
  }
  return {
    kind: "http",
    status: response.status,
    code,
    retryAfter: parseRetryAfter(response.headers.get("Retry-After"), Date.now()),
  };
}

function isAbort(error: unknown, signal: AbortSignal): boolean {
  return signal.aborted || (error instanceof Error && error.name === "AbortError");
}

/**
 * `POST <url>` with a JSON body and, when given, the bearer token. Resolves to the response when
 * its status is `expected`, to a `Failure` otherwise, or to `"aborted"` when `signal` aborted it.
 * `fetcher` replaces the global `fetch`, which is otherwise looked up when the request is made.
 */
export function postJson(
  url: string,
  body: unknown,
  token: string | null,
  expected: number,
  signal: AbortSignal,
  fetcher?: typeof fetch,
): Promise<Outcome<Response>> {
  return post(url, JSON.stringify(body), token, expected, signal, fetcher);
}

/**
 * `postJson` with any body: a string is sent as `application/json`; a `FormData` gets the
 * `multipart/form-data` type and boundary from `fetch` itself.
 */
export async function post(
  url: string,
  body: string | FormData,
  token: string | null,
  expected: number,
  signal: AbortSignal,
  fetcher?: typeof fetch,
): Promise<Outcome<Response>> {
  const headers: Record<string, string> =
    typeof body === "string" ? { "Content-Type": "application/json" } : {};
  if (token !== null) headers.Authorization = `Bearer ${token}`;
  const init: RequestInit = {
    method: "POST",
    headers,
    body,
    signal,
    credentials: "omit",
    cache: "no-store",
  };
  let response: Response;
  try {
    // Called as a plain function, never as a method of another object: a browser's `fetch`
    // throws "Illegal invocation" when its `this` is not the window.
    response = await (fetcher === undefined ? fetch(url, init) : fetcher(url, init));
  } catch (error) {
    return isAbort(error, signal) ? "aborted" : { ok: false, failure: { kind: "network" } };
  }
  if (response.status === expected) return { ok: true, value: response };
  const failure = await readFailure(response);
  return signal.aborted ? "aborted" : { ok: false, failure };
}

// SSE payload guards (docs/03 §8.2).

function oneOf(value: unknown, values: readonly string[]): boolean {
  return typeof value === "string" && values.includes(value);
}

function optionalString(value: unknown): boolean {
  return value === undefined || typeof value === "string";
}

function isStrings(value: unknown): value is string[] {
  return Array.isArray(value) && value.every((item) => typeof item === "string");
}

function isEvidence(value: unknown): boolean {
  return (
    isObject(value) &&
    typeof value.projectId === "string" &&
    typeof value.description === "string" &&
    (value.files === undefined || isStrings(value.files))
  );
}

function isRequirement(value: unknown): boolean {
  return (
    isObject(value) &&
    typeof value.requirement === "string" &&
    oneOf(value.importance, REQUIREMENT_IMPORTANCES) &&
    oneOf(value.match, REQUIREMENT_MATCHES) &&
    Array.isArray(value.evidence) &&
    value.evidence.every(isEvidence)
  );
}

/** The fields of `JobOfferReport` the report view and `renderReportText` read (docs/09 §5). */
export function isReport(value: unknown): value is JobOfferReport {
  return (
    isObject(value) &&
    typeof value.language === "string" &&
    typeof value.summary === "string" &&
    typeof value.disclaimer === "string" &&
    value.disclaimer !== "" &&
    Array.isArray(value.requirements) &&
    value.requirements.every(isRequirement) &&
    isStrings(value.gaps) &&
    isStrings(value.questionsForCandidate) &&
    isObject(value.input) &&
    typeof value.input.truncated === "boolean"
  );
}

function isSourceFile(value: unknown): value is SourceFile {
  return (
    isObject(value) &&
    typeof value.path === "string" &&
    oneOf(value.kind, SOURCE_KINDS) &&
    optionalString(value.projectId)
  );
}

/** Whether `data` is a valid payload of `event`, as far as the widget reads it. */
function validPayload(event: string, data: unknown): boolean {
  if (!isObject(data)) return false;
  switch (event) {
    case "progress":
      return (
        oneOf(data.stage, PROGRESS_STAGES) && optionalString(data.tool) && optionalString(data.path)
      );
    case "delta":
      return typeof data.text === "string";
    case "message":
      return (
        typeof data.text === "string" &&
        oneOf(data.mode, MESSAGE_MODES) &&
        oneOf(data.validation, MESSAGE_VALIDATIONS)
      );
    case "sources":
      return Array.isArray(data.files) && data.files.every(isSourceFile);
    case "result":
      return isReport(data.report);
    case "error":
      return typeof data.code === "string";
    case "done":
      return (
        typeof data.turnId === "string" &&
        optionalString(data.conversationId) &&
        oneOf(data.status, DONE_STATUSES)
      );
    default:
      return false;
  }
}

/**
 * Decodes a raw event: the event, `null` for an event name the contract does not know (a newer
 * service; ignored), or `"invalid"` for a known event with an unusable payload.
 */
export function decodeEvent(raw: RawSseEvent): SseEvent | null | "invalid" {
  if (!(SSE_EVENT_NAMES as readonly string[]).includes(raw.event)) {
    return null;
  }
  let data: unknown;
  try {
    data = JSON.parse(raw.data);
  } catch {
    return "invalid";
  }
  if (!validPayload(raw.event, data)) return "invalid";
  if (raw.event === "sources" && isObject(data) && Array.isArray(data.files)) {
    data.files = data.files.slice(0, SOURCES_MAX_FILES);
  }
  if (raw.event === "error" && isObject(data) && !isErrorCode(data.code)) {
    data.code = "internal_error";
  }
  // The guard above checked every field the widget reads for this event name.
  return { event: raw.event, data } as SseEvent;
}

/**
 * How a stream ended: after its `done` event (`done`), aborted by the caller (`aborted`), or
 * dropped: silent for the stall delay (`stalled`), its body ended or failed before `done`
 * (`closed`), or it carried a known event with an unusable payload (`invalid`).
 */
export type StreamEnd = "done" | "aborted" | "stalled" | "closed" | "invalid";

/** Whether the stream was dropped before its `done` event, for a reason the caller did not cause. */
export function isDropped(end: StreamEnd): end is "stalled" | "closed" | "invalid" {
  return end === "stalled" || end === "closed" || end === "invalid";
}

/**
 * Reads an SSE response to its `done` event, calling `onEvent` for each event in order. Resolves
 * to `"done"` after `done`, to `"aborted"` when `signal` aborted, and otherwise to why the stream
 * was dropped: `"stalled"` when it stayed silent for `stallMs`, `"invalid"` on an invalid event,
 * `"closed"` when the body ended or failed before `done`.
 */
export async function readStream(
  response: Response,
  onEvent: (event: SseEvent) => void,
  signal: AbortSignal,
  stallMs: number = CLIENT_STREAM_STALL_MS,
): Promise<StreamEnd> {
  const body = response.body;
  if (body === null) return "closed";
  const reader = body.getReader();
  const parser = new SseParser();
  let timer: ReturnType<typeof setTimeout> | undefined;
  let stalled = false;
  const cancel = (): void => {
    reader.cancel().catch(() => undefined);
  };
  const arm = (): void => {
    clearTimeout(timer);
    timer = setTimeout(() => {
      stalled = true;
      cancel();
    }, stallMs);
  };
  signal.addEventListener("abort", cancel, { once: true });
  arm();
  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (signal.aborted) return "aborted";
      if (done) return stalled ? "stalled" : "closed";
      arm();
      for (const raw of parser.push(value)) {
        const event = decodeEvent(raw);
        if (event === null) continue;
        if (event === "invalid") {
          cancel();
          return "invalid";
        }
        onEvent(event);
        if (event.event === "done") {
          cancel();
          return "done";
        }
      }
    }
  } catch {
    if (signal.aborted) return "aborted";
    return stalled ? "stalled" : "closed";
  } finally {
    clearTimeout(timer);
    signal.removeEventListener("abort", cancel);
  }
}
