// The zod-free part of the job-offer report contract (docs/09-job-offer-analysis.md §5, §6,
// §4.5): the payload enumerations, the fixed disclaimers and the plain-text rendering.
// `job-offer.ts` builds the schemas over these values and re-exports them; the widget imports them
// without bundling zod (docs/08-widget.md §12, S84 (a)).
import type { JobOfferReport } from "./job-offer.js";

export const REQUIREMENT_IMPORTANCES = ["must", "nice"] as const;
export const REQUIREMENT_MATCHES = ["strong", "partial", "none", "unknown"] as const;

/** Fixed disclaimer texts (docs/09 §6), inserted by the service, never written by the model. */
export const JOB_OFFER_DISCLAIMERS = Object.freeze({
  en: "This analysis was generated by an AI assistant from the content of this portfolio. It may be incomplete or wrong and must be reviewed by a human. It is not an assessment of the candidate and does not replace an interview.",
  fr: "Cette analyse a été générée par un assistant IA à partir du contenu de ce portfolio. Elle peut être incomplète ou erronée et doit être relue par un humain. Elle ne constitue pas une évaluation du candidat et ne remplace pas un entretien.",
});

/** `fr` when the report language is `fr`, `en` for every other language. */
export function jobOfferDisclaimer(language: string): string {
  return language === "fr" ? JOB_OFFER_DISCLAIMERS.fr : JOB_OFFER_DISCLAIMERS.en;
}

/** `must` requirements first, then the others, each group in its original order (docs/09 §8). */
export function orderRequirements<R extends { importance: string }>(
  requirements: readonly R[],
): R[] {
  return [
    ...requirements.filter((r) => r.importance === "must"),
    ...requirements.filter((r) => r.importance !== "must"),
  ];
}

/**
 * Renders a report to plain text for the pre-check and the judge (docs/09 §4.5): the widget's
 * order (§8), disclaimer excluded, empty sections omitted, `must` requirements before `nice`
 * (stable within each group). Deterministic: the same report always gives the same text.
 */
export function renderReportText(report: JobOfferReport): string {
  const sections: string[] = [];
  if (report.input.truncated) {
    sections.push("Note: the offer text was truncated before the analysis.");
  }
  sections.push(`Summary\n${report.summary}`);

  const ordered = orderRequirements(report.requirements);
  if (ordered.length > 0) {
    const rows = ordered.map((r) => {
      const lines = [`- ${r.requirement} (importance: ${r.importance}; match: ${r.match})`];
      for (const evidence of r.evidence) {
        const label =
          evidence.projectId === "profile" ? "profile" : `project ${evidence.projectId}`;
        lines.push(`  - Evidence from ${label}: ${evidence.description}`);
        if (evidence.files !== undefined && evidence.files.length > 0) {
          lines.push(`    Files: ${evidence.files.join(", ")}`);
        }
      }
      return lines.join("\n");
    });
    sections.push(`Requirements\n${rows.join("\n")}`);
  }
  if (report.gaps.length > 0) {
    sections.push(`Gaps\n${report.gaps.map((gap) => `- ${gap}`).join("\n")}`);
  }
  if (report.questionsForCandidate.length > 0) {
    const questions = report.questionsForCandidate.map((q) => `- ${q}`).join("\n");
    sections.push(`Questions for the candidate\n${questions}`);
  }
  return sections.join("\n\n");
}
