// Scope grammar (docs/02-architecture.md §6), without zod so that the widget can parse scopes
// without bundling the schemas (docs/08-widget.md §12 size budget). `scope.ts` holds the schemas
// and re-exports everything here.
//   scope      = "profile" | "all" | "project:" project-id
//   project-id = /^[a-z0-9][a-z0-9-]{0,63}$/

export const PROJECT_ID_PATTERN = /^[a-z0-9][a-z0-9-]{0,63}$/;

const SCOPE_PATTERN = new RegExp(
  `^(?:profile|all|project:${PROJECT_ID_PATTERN.source.slice(1, -1)})$`,
);

export type Scope = "profile" | "all" | `project:${string}`;

export type ParsedScope = { kind: "profile" } | { kind: "all" } | { kind: "project"; id: string };

/** Whether `value` is a string that matches the scope grammar. */
export function isScope(value: unknown): value is Scope {
  return typeof value === "string" && SCOPE_PATTERN.test(value);
}

/** Parses a scope string; returns `null` when it does not match the grammar. */
export function parseScope(value: string): ParsedScope | null {
  if (!isScope(value)) return null;
  if (value === "profile") return { kind: "profile" };
  if (value === "all") return { kind: "all" };
  return { kind: "project", id: value.slice("project:".length) };
}

/** Inverse of `parseScope`. */
export function formatScope(scope: ParsedScope): Scope {
  switch (scope.kind) {
    case "profile":
      return "profile";
    case "all":
      return "all";
    case "project":
      return `project:${scope.id}`;
  }
}
