// Entry of `dist/askfolio-client.js`, the headless client (D22, task 44): a client of one Askfolio
// service with no interface, for an integrator who builds their own. It rests on the client
// modules the widget uses (health, session, Turnstile, the SSE stream, the upload checks, the
// resend rule), so the contract of docs/03-api-contract.md has one implementation; only the
// class's own bookkeeping is here: the stored session (storage.ts), the conversation id, one turn
// at a time, and failures as results.
//
// Rule 1: loading this module and constructing the client make no request and read no storage;
// no method throws and no promise rejects, whatever the service, the storage or the page's own
// callbacks do. Rule 13: the official AI disclosure is exported, and a job-offer report without
// its `disclaimer` is refused (the stream guard of stream.ts), never delivered.
//
// The public declarations below are what `dist/askfolio-client.d.ts` ships: every public type is
// declared in this file and every public member has an explicit type, so the emitted declarations
// import nothing (scripts/build-types.mjs checks it). The types that restate shared shapes
// (`ErrorCode`, `Limits`, `SourceFile`, `Progress`, `JobOfferReport` and its parts, `Scope`) are
// kept identical to those of `@askfolio/shared` by test/client-types.test.ts, the exception that
// AGENTS.md "Shared contracts" names.
//
// A client module (task 44, the headless client): it imports only other client modules and
// zod-free values of `@askfolio/shared`, and touches no DOM at import time.
import {
  CLIENT_HEALTH_TIMEOUT_MS,
  codePointLength,
  type DoneEvent,
  isScope,
  JOB_OFFER_DISCLAIMERS,
  type MessageEvent,
  normaliseOfferText,
  normaliseVisitorText,
  type ProgressEvent,
  type JobOfferReport as ReportPayload,
  TURNSTILE_ACTION as SESSION_ACTION,
} from "@askfolio/shared";
import { AI_DISCLOSURE as DISCLOSURE } from "./disclosure.js";
import { checkHealth, type HealthResult } from "./health.js";
import { resendPlan } from "./resend.js";
import { readServiceUrl } from "./service-url.js";
import { DEFAULT_LIMITS, Session, type SessionFailure } from "./session.js";
import { SessionPersistence, type StorageChoice } from "./storage.js";
import { isDropped, isObject, type Outcome, post, postJson, readStream } from "./stream.js";
import { type ChallengeAppearance, type TokenSource, TurnstileChallenge } from "./turnstile.js";
