// ─── Basics ──────────────────────────────────────────────────────────────────

/**
 * What the assistant answers about: the owner's profile, everything, or one project
 * (`project:<id>`, id matching /^[a-z0-9][a-z0-9-]{0,63}$/). A conversation keeps one scope:
 * sending in another scope starts a new conversation.
 */
export type Scope = "profile" | "all" | `project:${string}`;

/**
 * What every operation resolves to. The client never throws and none of its promises
 * rejects, so a failure cannot break the page (rule 1). Branch on `ok`, then on `error.kind`.
 */
export type Result<T> = { ok: true; value: T } | { ok: false; error: AskfolioError };

/** The service's error codes (docs/03 §2). Map them to your own text; never show the service's `message`. */
export type ErrorCode =
  | "invalid_request"
  | "invalid_scope"
  | "turnstile_failed"
  | "origin_not_allowed"
  | "unauthorized"
  | "not_found"
  | "conversation_limit"
  | "payload_too_large"
  | "unsupported_media_type"
  | "document_unreadable"
  | "rate_limited"
  | "budget_exhausted"
  | "service_unavailable"
  | "internal_error";

/**
 * Why a client-side check refused an input. Nothing was sent.
 *
 * - `invalid_scope`: the scope does not match the grammar; `limit` is null.
 * - `message_empty`: nothing left after normalisation; `limit` is null.
 * - `message_too_long`: `limit` is `limits.maxMessageChars`.
 * - `offer_text_too_short`: `limit` is `limits.jobOfferMinTextChars` (an empty text too).
 * - `offer_text_too_long`: `limit` is `limits.jobOfferMaxTextChars`.
 * - `offer_pdf_type`: not declared as a PDF, or no `%PDF-` in its first 1024 bytes; `limit` is null.
 * - `offer_pdf_too_large`: `limit` is `limits.jobOfferMaxPdfBytes`.
 */
export type InputCode =
  | "invalid_scope"
  | "message_empty"
  | "message_too_long"
  | "offer_text_too_short"
  | "offer_text_too_long"
  | "offer_pdf_type"
  | "offer_pdf_too_large";

/** A refused input: the code, and the limit it broke when there is one. */
export type InputError = { kind: "input"; code: InputCode; limit: number | null };

/**
 * Why an operation failed. Each kind tells the page what it can do:
 *
 * - `http`: the service refused the request before any answer streamed. `retryAfter`, in
 *   seconds, comes from `Retry-After` and is set on `rate_limited` and `budget_exhausted`.
 *   `rate_limited` merges three causes (concurrency, session quota, IP quota) that the contract
 *   does not tell apart; only `retryAfter` differs. `unauthorized` and `not_found` reach the
 *   page only when the one automatic resend did not fix them. `origin_not_allowed` reaches
 *   the page only outside a browser: in a browser it is a `network` failure, see below.
 * - `stream`: the stream had opened, then the service sent an `error` event (`code` is
 *   `service_unavailable` when the turn passed its deadline or the model provider failed, else
 *   `internal_error`). The turn was not saved: the conversation does not contain it. A judge
 *   that fails or cannot be reached is not an error: the turn completes with a refusal
 *   (`validation: "refused"`).
 * - `network`: no HTTP answer the page may read: offline, DNS, the service unreachable, a
 *   Content Security Policy blocking `connect-src`, or a CORS refusal. A site origin missing
 *   from the service's ASKFOLIO_ALLOWED_ORIGINS shows up here, because the service refuses
 *   the preflight without CORS headers and the browser hides its answer. Health uses no
 *   preflight: if `health()` says available but `connect()` fails with `network`, check the
 *   allowed origins first.
 * - `dropped`: the stream ended before its last event: silent for 45 seconds (keepalives
 *   included), closed early, or carrying an event the client cannot read (for example a
 *   job-offer report without `disclaimer`, which the client refuses, rule 13). Its quota is
 *   spent. A chat turn dropped before its final text arrived (no `onText` call with
 *   `final: true`) was not saved. One dropped after the final text may have been saved: the
 *   service saves the turn once the final text is sent, just before the stream's last event,
 *   so the conversation may already contain the exchange, and the page should keep the final
 *   text it showed. Never resend automatically; let the visitor decide.
 * - `turnstile`: no session, because of Turnstile: the script did not load (`script`: network
 *   or CSP), the challenge failed or expired (`challenge`), no container was available
 *   (`container`), or the service refused the token (`rejected`, a `403 turnstile_failed`).
 *   The next `connect()` (or send) resets the challenge and tries again.
 * - `unavailable`: a session was needed, and health says the service cannot serve. Nothing
 *   else was sent. Hide or disable the chat (rule 1).
 * - `input`: a client-side check refused the input; nothing was sent.
 * - `busy`: another turn (message or job offer) is in flight on this client; nothing was sent.
 * - `aborted`: `stop()` or `destroy()` ended the operation.
 */
export type AskfolioError =
  | { kind: "http"; code: ErrorCode; status: number; retryAfter: number | null }
  | { kind: "stream"; code: ErrorCode }
  | { kind: "network" }
  | { kind: "dropped"; reason: "stalled" | "closed" | "invalid_event" }
  | { kind: "turnstile"; reason: "script" | "challenge" | "container" | "rejected" }
  | { kind: "unavailable"; status: "unavailable" | "budget_exhausted" }
  | InputError
  | { kind: "busy" }
  | { kind: "aborted" };

// ─── Health ──────────────────────────────────────────────────────────────────

/** What the page should do with its chat interface: show it, or hide or disable it. */
export type ServiceStatus = "available" | "unavailable" | "budget_exhausted";

/** The result of `health()`. It never fails: every failure is `unavailable`. */
export interface Health {
  status: ServiceStatus;
  /** With `budget_exhausted`: when to check again, in ms since epoch (the next 00:00 UTC). Otherwise null. */
  retryAt: number | null;
  /**
   * With `unavailable`: why, for your logs only; do not branch the interface on it.
   * `invalid_service_url` means the `serviceUrl` option was refused. Otherwise null.
   */
  reason:
    | "network"
    | "timeout"
    | "http_status"
    | "bad_response"
    | "no_snapshot"
    | "invalid_service_url"
    | null;
  /** When the answer arrived, in ms since epoch. */
  checkedAt: number;
}

// ─── Session ─────────────────────────────────────────────────────────────────

/** The limits of a session (docs/03 §4.1). Before any session, the service's default values. */
export interface Limits {
  messagesPerSession: number;
  jobOffersPerSession: number;
  maxMessageChars: number;
  maxTurnsPerConversation: number;
  jobOfferMaxPdfBytes: number;
  jobOfferMaxPdfPages: number;
  jobOfferMaxTextChars: number;
  jobOfferMinTextChars: number;
}

/** The current session. The token itself is never exposed. */
export interface SessionInfo {
  /** ISO 8601 UTC. The session ends then, whatever happens; the next send creates a new one. */
  expiresAt: string;
  limits: Limits;
}

/** The conversation the next message continues. */
export interface Conversation {
  id: string;
  scope: Scope;
}

/**
 * The subset of the Web Storage API the client uses, to inject a store of your own (tests,
 * Node). The client writes one key, `askfolio:session:<serviceUrl>`, holding the session
 * token, its expiry, the limits, the conversation id and its scope, as JSON.
 */
export interface SessionStore {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
}

/**
 * Where Turnstile runs. Either give a container, and the client loads Cloudflare's script
 * when a session is needed (never at load), renders the challenge in a child element it adds
 * to the container, and removes that child once the session exists; or give `getToken`, if
 * you render Turnstile yourself (action `TURNSTILE_ACTION`) or run without a browser.
 */
export type TurnstileOptions =
  | {
      /**
       * The element the challenge goes in, or a function returning it when needed (for an
       * interface rendered later). Keep it in the layout whenever the chat can send: a
       * session may be renewed during a send, and an interactive challenge must be visible.
       * It is empty except while a challenge is shown, so `:empty { display: none }` works.
       */
      container: HTMLElement | (() => HTMLElement | null);
      /** Default "auto". */
      theme?: "auto" | "light" | "dark";
      /** Default "normal". "flexible" fills the container's width. */
      size?: "normal" | "flexible" | "compact";
      /** Default "always". "interaction-only" shows the challenge only when the visitor must act. */
      appearance?: "always" | "interaction-only";
    }
  | {
      /**
       * Returns a fresh Turnstile token for `siteKey`, or null on failure. Called once per
       * session attempt; a token is single-use. Cloudflare's test keys give the dummy token
       * `XXXX.DUMMY.TOKEN.XXXX`, accepted only by a service running with the test secret.
       */
      getToken: (siteKey: string, signal: AbortSignal) => Promise<string | null>;
    };

/** Options of `new AskfolioClient()`. */
export interface AskfolioClientOptions {
  /** The service's base URL, for example "https://askfolio-jane.fly.dev". http(s), no query or fragment. */
  serviceUrl: string;
  turnstile: TurnstileOptions;
  /**
   * Where the session is kept between page loads. "session" (default) uses `sessionStorage`:
   * a page load in the same tab keeps the session and the conversation, until the tab closes
   * or the session expires; it falls back to memory when the storage is unavailable or refuses
   * a write. "memory" keeps nothing across page loads. Never `localStorage`, never a cookie.
   */
  storage?: "session" | "memory" | SessionStore;
  /**
   * The `fetch` to use; defaults to the global one, looked up when a request is made. Outside a
   * browser, wrap it to add an `Origin` header the service allows: browsers send it, Node does not.
   */
  fetch?: typeof fetch;
}

// ─── Turns ───────────────────────────────────────────────────────────────────

/** A step of the work in progress (docs/03 §8.2). Show it as a transient status line. */
export interface Progress {
  stage: "exploring" | "writing" | "verifying";
  /** With "exploring": the tool called. Absent while a job offer's requirements are being read. */
  tool?: "list_files" | "search_files" | "read_file";
  /** With a tool: the virtual path it was called on. A name, never content. */
  path?: string;
}

/** A file the answer was built from. Names only, never content, for every tier. */
export interface SourceFile {
  path: string;
  kind: "profile" | "index" | "card" | "file";
  /** Present for "card" and "file". */
  projectId?: string;
  /** Present for "card" and "file". */
  tier?: "public" | "private" | "summary-only";
}

/** A chat message to send, and what to call while the answer arrives. */
export interface MessageRequest {
  scope: Scope;
  /** Normalised and checked against `limits.maxMessageChars` before anything is sent. */
  message: string;
  /**
   * The whole text to show so far: replace what you show with it, never append. Called as the
   * answer streams, and once more with `final: true` and the authoritative text, which may
   * differ from what streamed (a turn that switched to checked mode mid-way streams only a
   * prefix). A checked answer arrives in one call. It is Markdown: render it with
   * `renderMarkdown` from askfolio-markdown.js, or as text; never with `innerHTML`.
   */
  onText?: (text: string, final: boolean) => void;
  /** Work in progress. During streaming it is transient: the next `onText` means text resumed. */
  onProgress?: (progress: Progress) => void;
  /**
   * The conversation this message continued is gone (session expired or purged): the message
   * is being resent once, in a new conversation, and the assistant no longer has the earlier
   * context. Called before the new answer starts; tell the visitor.
   */
  onConversationExpired?: () => void;
}

/** A completed answer. */
export interface Answer {
  /** The authoritative final Markdown, the same text as the last `onText` call. */
  text: string;
  /** "buffered": the answer was checked before delivery, or the turn switched to checked mode. */
  mode: "streamed" | "buffered";
  /** "refused": `text` is the fixed refusal. "rewritten": the answer was rewritten after a check. */
  validation: "not_required" | "passed" | "rewritten" | "refused";
  sources: SourceFile[];
  turnId: string;
  /**
   * The conversation the turn was saved in; `client.conversation` now points to it, unless
   * `newConversation()` or `forget()` was called during the turn. Null if not saved.
   */
  conversationId: string | null;
}

/**
 * A job offer: pasted text, or a PDF. The PDF goes to the service only, as the form field
 * `file` with the fixed file name `offer.pdf`: the visitor's own file name never leaves the
 * browser. Nothing is stored.
 */
export type OfferInput = { text: string } | { pdf: Blob };

/** A job offer to send, and what to call while it is analysed. */
export type OfferRequest = OfferInput & {
  onProgress?: (progress: Progress) => void;
};

/** A job-offer report (docs/09 §5). Render it as structured text, never as HTML. */
export interface JobOfferReport {
  formatVersion: 1;
  /** ISO 639-1 code of the offer's language. */
  language: string;
  summary: string;
  requirements: Requirement[];
  gaps: string[];
  questionsForCandidate: string[];
  /** The fixed notice that the analysis is AI-generated. Always present; show it first. */
  disclaimer: string;
  input: { kind: "text" | "pdf"; characters: number; pages?: number; truncated: boolean };
}

export interface Requirement {
  requirement: string;
  importance: "must" | "nice";
  match: "strong" | "partial" | "none" | "unknown";
  evidence: Evidence[];
}

export interface Evidence {
  /** "profile", or a project id. */
  projectId: string;
  description: string;
  /** Virtual paths, public projects only. */
  files?: string[];
}

/** What a job offer gives: a report, or a refusal to show as text. */
export type OfferOutcome =
  | { kind: "report"; report: JobOfferReport; sources: SourceFile[]; turnId: string }
  | { kind: "refused"; text: string; sources: SourceFile[]; turnId: string };

// ─── Internals ───────────────────────────────────────────────────────────────

const LOG_PREFIX = "[askfolio-client]";

/** Logs to the console; never throws, even with a console replaced by the page. */
function log(message: string, error?: unknown): void {
  try {
    if (error === undefined) console.error(`${LOG_PREFIX} ${message}`);
    else console.error(`${LOG_PREFIX} ${message}`, error);
  } catch {
    // Nothing else can report it.
  }
}

const ABORTED: AskfolioError = Object.freeze({ kind: "aborted" });
const BUSY: AskfolioError = Object.freeze({ kind: "busy" });
const NETWORK: AskfolioError = Object.freeze({ kind: "network" });

function failed<T>(error: AskfolioError): Result<T> {
  return { ok: false, error };
}

function inputError(code: InputCode, limit: number | null = null): InputError {
  return { kind: "input", code, limit };
}

/** A step that either went through or failed with what the page sees. */
type Step = { ok: true } | { ok: false; error: AskfolioError };

function nextUtcMidnight(now: number): number {
  const date = new Date(now);
  return Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate() + 1);
}

function unavailableHealth(reason: Health["reason"]): Health {
  return { status: "unavailable", retryAt: null, reason, checkedAt: Date.now() };
}

function healthOf(result: HealthResult): Health {
  switch (result.state) {
    case "idle":
      return { status: "available", retryAt: null, reason: null, checkedAt: result.at };
    case "budget-exhausted":
      return {
        status: "budget_exhausted",
        retryAt: nextUtcMidnight(result.at),
        reason: null,
        checkedAt: result.at,
      };
    case "unavailable":
      return { status: "unavailable", retryAt: null, reason: result.reason, checkedAt: result.at };
  }
}

/** What the page sees of a failed request or session creation. */
function errorOf(failure: SessionFailure): AskfolioError {
  switch (failure.kind) {
    case "turnstile":
      return { kind: "turnstile", reason: failure.reason };
    case "network":
      return NETWORK;
    case "http":
      return failure.code === "turnstile_failed"
        ? { kind: "turnstile", reason: "rejected" }
        : {
            kind: "http",
            code: failure.code,
            status: failure.status,
            retryAfter: failure.retryAfter,
          };
  }
}

/** Resolves to `promise`'s value, or to `"aborted"` as soon as `signal` aborts. */
function unlessAborted<T>(promise: Promise<T>, signal: AbortSignal): Promise<T | "aborted"> {
  if (signal.aborted) return Promise.resolve("aborted");
  return new Promise<T | "aborted">((resolve, reject) => {
    const abort = (): void => resolve("aborted");
    signal.addEventListener("abort", abort, { once: true });
    promise.then(
      (value) => {
        signal.removeEventListener("abort", abort);
        resolve(value);
      },
      (error: unknown) => {
        signal.removeEventListener("abort", abort);
        reject(error);
      },
    );
  });
}

function progressOf(data: ProgressEvent): Progress {
  return {
    stage: data.stage,
    ...(data.tool === undefined ? {} : { tool: data.tool }),
    ...(data.path === undefined ? {} : { path: data.path }),
  };
}

function isElement(value: unknown): value is HTMLElement {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Partial<HTMLElement>;
  return (
    typeof candidate.append === "function" &&
    typeof candidate.ownerDocument === "object" &&
    candidate.ownerDocument !== null
  );
}

function isBlob(value: unknown): value is Blob {
  return typeof Blob !== "undefined" && value instanceof Blob;
}

/** A token source that never throws or rejects: any failure is a failed challenge. */
function guarded(source: TokenSource): TokenSource {
  return {
    async token(siteKey, signal) {
      try {
        return await source.token(siteKey, signal);
      } catch (error) {
        log("the Turnstile challenge failed", error);
        return { reason: "challenge" };
      }
    },
    remove() {
      try {
        source.remove();
      } catch (error) {
        log("removing the Turnstile challenge failed", error);
      }
    },
  };
}

const APPEARANCE_KEYS = ["theme", "size", "appearance"] as const;

/** The token source of the `turnstile` option: a container, `getToken`, or nothing usable. */
function tokenSource(turnstile: unknown): TokenSource {
  if (isObject(turnstile) && typeof turnstile.getToken === "function") {
    const options = turnstile;
    return guarded({
      async token(siteKey, signal) {
        // A token that never comes must not hold the client once the signal aborts.
        const token: unknown = await unlessAborted(
          Promise.resolve((options.getToken as (...args: unknown[]) => unknown)(siteKey, signal)),
          signal,
        );
        return typeof token === "string" && token !== "" && token !== "aborted"
          ? token
          : { reason: "challenge" };
      },
      remove() {
        // The page renders and removes its own challenge.
      },
    });
  }
  if (isObject(turnstile) && turnstile.container !== undefined && turnstile.container !== null) {
    const container = turnstile.container;
    const parent = (): HTMLElement | null => {
      let element: unknown;
      try {
        element = typeof container === "function" ? (container as () => unknown)() : container;
      } catch (error) {
        log("the Turnstile container function threw", error);
        return null;
      }
      return isElement(element) ? element : null;
    };
    const appearance: Record<string, unknown> = {};
    for (const key of APPEARANCE_KEYS) {
      if (typeof turnstile[key] === "string") appearance[key] = turnstile[key];
    }
    return guarded(new TurnstileChallenge(parent, appearance as ChallengeAppearance));
  }
  log("the turnstile option has neither a container nor getToken: no session can be created");
  return NO_TOKENS;
}

/** No way to get a Turnstile token: every session attempt fails with `container`. */
const NO_TOKENS: TokenSource = Object.freeze({
  token: () => Promise.resolve({ reason: "container" as const }),
  remove: () => undefined,
});

function storageChoice(storage: unknown): StorageChoice {
  if (storage === undefined || storage === "session") return "session";
  if (storage === "memory") return "memory";
  if (isObject(storage)) return storage as StorageChoice;
  log('the storage option is not "session", "memory" or a store: memory is used');
  return "memory";
}

function readOptions(options: unknown): {
  serviceUrl: string | null;
  turnstile: unknown;
  storage: unknown;
  fetcher: typeof fetch | undefined;
} {
  try {
    if (!isObject(options)) return empty();
    const url = options.serviceUrl;
    const fetcher = options.fetch;
    return {
      serviceUrl: typeof url === "string" ? readServiceUrl(url) : null,
      turnstile: options.turnstile,
      storage: options.storage,
      fetcher: typeof fetcher === "function" ? (fetcher as typeof fetch) : undefined,
    };
  } catch {
    return empty();
  }
}

function empty() {
  return { serviceUrl: null, turnstile: undefined, storage: undefined, fetcher: undefined };
}

// ─── The client ──────────────────────────────────────────────────────────────

/**
 * A client of one Askfolio service, with no interface: the page owns every visual and every
 * interface state. Create one per page. Loading this module and constructing the client make
 * no request and read no storage.
 */
export class AskfolioClient {
  readonly #serviceUrl: string | null;
  readonly #fetcher: typeof fetch | undefined;
  /** Aborted by `destroy`: every request, the turn in flight and a session being created. */
  readonly #abort = new AbortController();
  readonly #tokens: TokenSource;
  /**
   * `null` with an invalid `serviceUrl`: nothing is ever requested or stored. Replaced by
   * `forget`, so that a creation it abandons is not shared with the next attempt.
   */
  #session: Session | null;
  /** The signal of `#session`'s creations: aborted by `forget` (then renewed) and by `destroy`. */
  #creation = new AbortController();
  readonly #persistence: SessionPersistence | null;
  /** Whether the stored session was read; it is read on first need, never at construction. */
  #loaded = false;
  #destroyed = false;
  #siteKey: string | null = null;
  #conversation: Conversation | null = null;
  /** Incremented by `newConversation` and `forget`: a turn begun before does not set its id. */
  #generation = 0;
  /** The turn in flight, aborted by `stop`, `forget` and `destroy`. */
  #turn: AbortController | null = null;
  /** The session being created, shared by `connect` and the sends; dropped by `forget`. */
  #establishing: Promise<Step> | null = null;

  /** Never throws. An invalid `serviceUrl` is logged once; `health()` then says `unavailable`. */
  constructor(options: AskfolioClientOptions) {
    const { serviceUrl, turnstile, storage, fetcher } = readOptions(options);
    this.#serviceUrl = serviceUrl;
    this.#fetcher = fetcher;
    let tokens: TokenSource;
    try {
      tokens = tokenSource(turnstile);
    } catch (error) {
      log("the turnstile option could not be read: no session can be created", error);
      tokens = NO_TOKENS;
    }
    this.#tokens = tokens;
    if (serviceUrl === null) {
      log("invalid serviceUrl option (an absolute http(s) URL, no query or fragment): unavailable");
      this.#session = null;
      this.#persistence = null;
      return;
    }
    this.#abort.signal.addEventListener("abort", () => this.#creation.abort(), { once: true });
    this.#session = this.#newSession(serviceUrl);
    this.#persistence = new SessionPersistence(storageChoice(storage), serviceUrl);
  }

  /**
   * Calls the service's health endpoint (5 s timeout) and says whether to show the chat.
   * Call it when the page loads and when the visitor opens the chat. The client never calls it
   * on its own, except inside `connect()` when it has not seen the Turnstile site key yet.
   */
  async health(): Promise<Health> {
    try {
      if (this.#destroyed) return unavailableHealth(null);
      if (this.#serviceUrl === null) return unavailableHealth("invalid_service_url");
      const result = await checkHealth(
        this.#serviceUrl,
        this.#abort.signal,
        CLIENT_HEALTH_TIMEOUT_MS,
        this.#fetcher,
      );
      if (result === null) return unavailableHealth(null);
      if (result.siteKey !== null) this.#siteKey = result.siteKey;
      return healthOf(result);
    } catch (error) {
      log("health failed unexpectedly", error);
      return unavailableHealth("network");
    }
  }

  /**
   * Makes sure a session exists. Resolves at once with a session restored from storage or
   * created earlier; otherwise runs Turnstile and creates one (calling health first if needed).
   * Optional: a send connects by itself. Call it when the visitor opens the chat or focuses
   * the input, so that the challenge runs while they type. Concurrent calls share one attempt.
   * A restored session is trusted until the service refuses it; the next send then renews it.
   */
  async connect(): Promise<Result<SessionInfo>> {
    try {
      if (this.#destroyed) return failed(ABORTED);
      const session = this.#session;
      if (session === null) return failed({ kind: "unavailable", status: "unavailable" });
      this.#load();
      if (!session.ready) {
        const step = await unlessAborted(this.#establish(), this.#abort.signal);
        if (step === "aborted") return failed(ABORTED);
        if (!step.ok) return failed(step.error);
      }
      // Null only when `forget()` or `destroy()` ended the attempt meanwhile.
      const info = this.#sessionInfo();
      return info === null ? failed(ABORTED) : { ok: true, value: info };
    } catch (error) {
      log("connect failed unexpectedly", error);
      return failed(NETWORK);
    }
  }

  /**
   * Sends a message and delivers its answer. One turn at a time per client: a send during
   * another turn resolves to `busy` without a request. Continues `conversation` when its scope
   * equals `request.scope`, otherwise starts a new conversation. On a refused session (`401`)
   * the client creates a new one and resends once in a new conversation; on a conversation
   * the service no longer knows (`404`) it resends once in a new conversation; when the message
   * continued a conversation, both call `onConversationExpired`. A request the service admits
   * spends one message of the session's and the visitor's quotas, whatever happens next (a
   * dropped or stopped turn included); a request it refuses before admission (`401`, `404`,
   * `409`, `429`, `503`) spends none. The client cannot tell how much quota is left: do not
   * count it down from the number of sends.
   */
  async sendMessage(request: MessageRequest): Promise<Result<Answer>> {
    if (this.#destroyed) return failed(ABORTED);
    if (this.#turn !== null) return failed(BUSY);
    let turn: AbortController | null = null;
    try {
      const given: Partial<MessageRequest> = isObject(request) ? request : {};
      const scope = given.scope;
      if (!isScope(scope)) return failed(inputError("invalid_scope"));
      const message = normaliseVisitorText(typeof given.message === "string" ? given.message : "");
      const length = codePointLength(message);
      if (length === 0) return failed(inputError("message_empty"));
      const session = this.#session;
      if (session === null) return failed({ kind: "unavailable", status: "unavailable" });
      this.#load();
      const max = session.limits.maxMessageChars;
      if (length > max) return failed(inputError("message_too_long", max));
      turn = this.#startTurn();
      return await this.#runMessage(session, scope, message, given, turn.signal);
    } catch (error) {
      log("sendMessage failed unexpectedly", error);
      return failed(NETWORK);
    } finally {
      if (turn !== null) this.#endTurn(turn);
    }
  }

  /**
   * Checks a job offer as `sendOffer` will, without sending it: for an inline error as soon as
   * the visitor picks a file or types. Uses the session's limits, or the defaults before a session.
   */
  async checkOffer(input: OfferInput): Promise<InputError | null> {
    try {
      this.#load();
      const checked = await this.#checkOffer(input);
      return "error" in checked ? checked.error : null;
    } catch (error) {
      log("checkOffer failed unexpectedly", error);
      return null;
    }
  }

  /**
   * Checks, then sends a job offer, and delivers its report. Same rules as `sendMessage`: one
   * turn at a time, one resend after a `401`. The service answers `document_unreadable` for a
   * PDF it cannot read (scanned, encrypted, too many pages), as an `http` error.
   */
  async sendOffer(request: OfferRequest): Promise<Result<OfferOutcome>> {
    if (this.#destroyed) return failed(ABORTED);
    if (this.#turn !== null) return failed(BUSY);
    // Taken before the check, which reads the file: a second send meanwhile is `busy`.
    const turn = this.#startTurn();
    try {
      const session = this.#session;
      this.#load();
      const checked = await this.#checkOffer(request);
      if (turn.signal.aborted) return failed(ABORTED);
      if ("error" in checked) return failed(checked.error);
      if (session === null) return failed({ kind: "unavailable", status: "unavailable" });
      const onProgress = isObject(request) ? request.onProgress : undefined;
      return await this.#runOffer(checked.upload, onProgress, turn.signal);
    } catch (error) {
      log("sendOffer failed unexpectedly", error);
      return failed(NETWORK);
    } finally {
      this.#endTurn(turn);
    }
  }

  /**
   * Stops the turn in flight, which resolves to `aborted`; does nothing without one. Its
   * quota is spent. A turn stopped before its final text arrived is not saved: the
   * conversation does not contain it. One stopped after the final text (`onText` with
   * `final: true`) may already be saved. The service frees the session's stream slot only
   * when it sees the connection close, so a send right after a stop may get `rate_limited`
   * with a short `retryAfter` (5 s): wait that long, then let the visitor resend. A session
   * being created for the turn is not cancelled; it is kept for the next send.
   */
  stop(): void {
    try {
      this.#turn?.abort();
    } catch (error) {
      log("stop failed unexpectedly", error);
    }
  }

  /** Forgets the conversation id: the next message starts a new conversation in its scope. */
  newConversation(): void {
    try {
      if (this.#destroyed) return;
      this.#load();
      this.#generation += 1;
      this.#conversation = null;
      this.#persist();
    } catch (error) {
      log("newConversation failed unexpectedly", error);
    }
  }

  /**
   * Forgets the session and the conversation, in memory and in storage, and stops the turn in
   * flight. The next send needs a new session (a new Turnstile check).
   */
  forget(): void {
    try {
      if (this.#destroyed) return;
      this.#load();
      this.#turn?.abort();
      this.#generation += 1;
      this.#conversation = null;
      // A session being created is abandoned: its Turnstile check and its request abort, whoever
      // waits on it gets `aborted`, and the next attempt starts at once, in a new `Session`.
      this.#creation.abort();
      this.#creation = new AbortController();
      this.#establishing = null;
      const forgotten = this.#session;
      if (forgotten !== null && this.#serviceUrl !== null) {
        this.#session = this.#newSession(this.#serviceUrl);
        forgotten.discard();
      }
      this.#persistence?.remove();
      this.#tokens.remove();
    } catch (error) {
      log("forget failed unexpectedly", error);
    }
  }

  /**
   * Stops everything, removes the Turnstile challenge and makes the client inert. Afterwards
   * `connect()`, `sendMessage()` and `sendOffer()` resolve to `aborted` without a request;
   * `health()` makes no request and resolves to `unavailable`; `checkOffer()` still checks,
   * since it sends nothing; the getters keep their last values. Storage is kept, so a new
   * client on the next page restores the session. For an interface that unmounts; a full page
   * load needs no call.
   */
  destroy(): void {
    if (this.#destroyed) return;
    this.#destroyed = true;
    try {
      this.#abort.abort();
    } catch (error) {
      log("destroy failed unexpectedly", error);
    }
    this.#tokens.remove();
  }

  /** Whether a turn (message or job offer) is in flight. */
  get busy(): boolean {
    return this.#turn !== null;
  }

  /** The session, restored or created; null before one exists or after it was refused. */
  get session(): SessionInfo | null {
    this.#load();
    return this.#sessionInfo();
  }

  /** The session's limits, or the service's defaults before a session. For counters and inline checks. */
  get limits(): Limits {
    this.#load();
    return this.#session?.limits ?? DEFAULT_LIMITS;
  }

  /** The conversation the next message in the same scope continues; null before the first saved turn. */
  get conversation(): Conversation | null {
    this.#load();
    return this.#conversation;
  }

  // Session and storage.

  /** Reads the stored session once, on first need; never after `destroy`. */
  #load(): void {
    if (this.#loaded || this.#destroyed) return;
    this.#loaded = true;
    const session = this.#session;
    const saved = this.#persistence?.read(Date.now()) ?? null;
    if (session === null || saved === null) return;
    session.restore(saved);
    this.#conversation =
      saved.conversation === null ? null : Object.freeze({ ...saved.conversation });
  }

  /** Writes the session and the conversation, or removes the entry when there is no session. */
  #persist(): void {
    const persistence = this.#persistence;
    if (!this.#loaded || this.#destroyed || persistence === null) return;
    const snapshot = this.#session?.snapshot() ?? null;
    if (snapshot === null) persistence.remove();
    else persistence.write({ ...snapshot, conversation: this.#conversation });
  }

  /** A `Session` created with the current creation signal; once replaced, it writes nothing. */
  #newSession(serviceUrl: string): Session {
    const session = new Session(serviceUrl, this.#creation.signal, this.#tokens, this.#fetcher);
    session.onChange = () => {
      if (this.#session === session) this.#persist();
    };
    return session;
  }

  #sessionInfo(): SessionInfo | null {
    const session = this.#session;
    const expiresAt = session?.expiresAt ?? null;
    if (session === null || !session.ready || expiresAt === null) return null;
    return { expiresAt, limits: session.limits };
  }

  /**
   * Drops the session and, with it, the conversation, which belongs to it (docs/03 §5): in
   * memory and in storage.
   */
  #dropSession(): void {
    this.#conversation = null;
    // `discard` calls `onChange`, which removes the stored entry.
    this.#session?.discard();
  }

  #establish(): Promise<Step> {
    if (this.#establishing === null) {
      const signal = this.#creation.signal;
      // Settles at once when `forget` or `destroy` abandons it, whatever it is waiting on.
      const attempt = unlessAborted(this.#createSession(signal), signal).then(
        (step): Step => (step === "aborted" ? { ok: false, error: ABORTED } : step),
      );
      this.#establishing = attempt;
      const clear = (): void => {
        if (this.#establishing === attempt) this.#establishing = null;
      };
      attempt.then(clear, clear);
    }
    return this.#establishing;
  }

  /** `signal` aborts when `forget` or `destroy` abandons the attempt: nothing of it is kept. */
  async #createSession(signal: AbortSignal): Promise<Step> {
    const session = this.#session;
    if (session === null)
      return { ok: false, error: { kind: "unavailable", status: "unavailable" } };
    if (this.#siteKey === null) {
      const health = await this.health();
      if (signal.aborted) return { ok: false, error: ABORTED };
      if (health.status !== "available") {
        return { ok: false, error: { kind: "unavailable", status: health.status } };
      }
    }
    const siteKey = this.#siteKey;
    if (siteKey === null)
      return { ok: false, error: { kind: "unavailable", status: "unavailable" } };
    const outcome = await session.create(siteKey, () => undefined);
    // A session created just before `forget()` was discarded by it; `destroy()` keeps it.
    if (outcome === "aborted" || signal.aborted) return { ok: false, error: ABORTED };
    if (!outcome.ok) return { ok: false, error: errorOf(outcome.failure) };
    if (session.expiresAt === null) {
      // The response's expiry cannot be read: the session could be neither persisted nor
      // shown, so it is treated as an unusable response, as the session guard treats others.
      session.discard();
      return {
        ok: false,
        error: { kind: "http", code: "internal_error", status: 201, retryAfter: null },
      };
    }
    return { ok: true };
  }

  // Turns.

  /** The turn in flight: its signal aborts on `stop`, `forget` and `destroy`. */
  #startTurn(): AbortController {
    const turn = new AbortController();
    this.#turn = turn;
    this.#abort.signal.addEventListener("abort", this.#stopTurn, { once: true });
    return turn;
  }

  #endTurn(turn: AbortController): void {
    this.#abort.signal.removeEventListener("abort", this.#stopTurn);
    if (this.#turn === turn) this.#turn = null;
  }

  readonly #stopTurn = (): void => {
    this.#turn?.abort();
  };

  /**
   * Calls a callback of the page; one that throws or rejects is logged and ignored. Any thenable
   * it returns gets a rejection handler, a promise of another realm (an iframe) included, which
   * `instanceof Promise` misses; a `then` that throws is caught here.
   */
  #call<A extends unknown[]>(callback: ((...args: A) => unknown) | undefined, ...args: A): void {
    if (typeof callback !== "function") return;
    try {
      const value: unknown = callback(...args);
      if ((typeof value === "object" && value !== null) || typeof value === "function") {
        const then: unknown = (value as { then?: unknown }).then;
        if (typeof then === "function") {
          then.call(value, undefined, (error: unknown) => log("a callback rejected", error));
        }
      }
    } catch (error) {
      log("a callback threw", error);
    }
  }

  /**
   * Makes sure a session exists, then posts with it; on a failure `resendPlan` says to resend,
   * resends once, without the conversation. Resolves to the response, or to the failure the
   * page sees.
   */
  async #postWithSession(
    session: Session,
    signal: AbortSignal,
    conversationId: string | undefined,
    send: (bearer: string, conversationId: string | undefined) => Promise<Outcome<Response>>,
    onConversationExpired: (() => void) | undefined,
  ): Promise<{ ok: true; response: Response } | { ok: false; error: AskfolioError }> {
    let conversation = conversationId;
    for (let resent = false; ; resent = true) {
      if (!session.ready) {
        const step = await unlessAborted(this.#establish(), signal);
        if (step === "aborted") return { ok: false, error: ABORTED };
        if (!step.ok) return step;
      }
      const bearer = session.bearer();
      if (bearer === null) return { ok: false, error: signal.aborted ? ABORTED : NETWORK };
      const result = await send(bearer, conversation);
      if (result === "aborted" || signal.aborted) return { ok: false, error: ABORTED };
      if (result.ok) return { ok: true, response: result.value };
      const failure = result.failure;
      const plan = resendPlan(failure, {
        hasConversation: conversation !== undefined,
        alreadyResent: resent,
      });
      // A refused session is dropped even when it is not resent: the next send renews it.
      if (failure.kind === "http" && failure.code === "unauthorized") this.#dropSession();
      if (plan === null) return { ok: false, error: errorOf(failure) };
      if (plan === "drop_conversation" && this.#conversation?.id === conversation) {
        this.#conversation = null;
        this.#persist();
      }
      if (conversation !== undefined) this.#call(onConversationExpired);
      conversation = undefined;
    }
  }

  async #runMessage(
    session: Session,
    scope: Scope,
    message: string,
    request: Partial<MessageRequest>,
    signal: AbortSignal,
  ): Promise<Result<Answer>> {
    const generation = this.#generation;
    // A conversation keeps one scope (docs/03 §5): another scope starts a new one.
    if (this.#conversation !== null && this.#conversation.scope !== scope) {
      this.#conversation = null;
      this.#persist();
    }
    // A session is trusted until the service refuses it: its expiry is compared with the
    // visitor's clock only when it is restored (storage.ts), since a clock hours ahead would
    // otherwise drop every new session, and the conversation with it, at each send.
    const conversationId = this.#conversation?.id;
    const url = `${this.#serviceUrl}/v1/chat`;
    const posted = await this.#postWithSession(
      session,
      signal,
      conversationId,
      (bearer, conversation) =>
        postJson(
          url,
          {
            scope,
            message,
            ...(conversation === undefined ? {} : { conversationId: conversation }),
          },
          bearer,
          200,
          signal,
          this.#fetcher,
        ),
      request.onConversationExpired,
    );
    if (!posted.ok) return failed(posted.error);

    let text = "";
    let final: MessageEvent | null = null;
    let sources: SourceFile[] = [];
    let done: DoneEvent | null = null;
    let errorCode: ErrorCode | null = null;
    const end = await readStream(
      posted.response,
      (event) => {
        if (signal.aborted) return;
        switch (event.event) {
          case "progress":
            this.#call(request.onProgress, progressOf(event.data));
            break;
          case "delta":
            // Deltas after the final message would be a service fault; the message stands.
            if (final !== null) break;
            text += event.data.text;
            this.#call(request.onText, text, false);
            break;
          case "message":
            // Authoritative: it replaces what streamed (docs/03 §8.3).
            final = event.data;
            this.#call(request.onText, event.data.text, true);
            break;
          case "sources":
            sources = event.data.files;
            break;
          case "error":
            errorCode = event.data.code;
            break;
          case "done":
            done = event.data;
            break;
          default:
            // `result` belongs to a job-offer stream.
            break;
        }
      },
      signal,
    );
    if (end === "aborted" || signal.aborted) return failed(ABORTED);
    if (isDropped(end)) {
      return failed({ kind: "dropped", reason: end === "invalid" ? "invalid_event" : end });
    }
    const answer = final as MessageEvent | null;
    const last = done as DoneEvent | null;
    const code = errorCode as ErrorCode | null;
    if (code !== null || last === null || last.status === "error" || answer === null) {
      return failed({ kind: "stream", code: code ?? "internal_error" });
    }
    const savedIn = last.conversationId ?? null;
    if (savedIn !== null && generation === this.#generation && !this.#destroyed) {
      this.#conversation = Object.freeze({ id: savedIn, scope });
      this.#persist();
    }
    return {
      ok: true,
      value: {
        text: answer.text,
        mode: answer.mode,
        validation: answer.validation,
        sources,
        turnId: last.turnId,
        conversationId: savedIn,
      },
    };
  }

  // Job offers (docs/09-job-offer-analysis.md, docs/03 §7).

  /** The input checked with the current limits: what to send, or why not. */
  async #checkOffer(input: unknown): Promise<{ upload: Upload } | { error: InputError }> {
    const limits = this.#session?.limits ?? DEFAULT_LIMITS;
    const given = isObject(input) ? input : {};
    if (given.pdf !== undefined && given.pdf !== null) {
      if (!isBlob(given.pdf)) return { error: inputError("offer_pdf_type") };
      const problem = await checkPdf(given.pdf, limits);
      return problem === null
        ? { upload: { kind: "pdf", file: given.pdf } }
        : { error: inputError(problem.code, problem.limit) };
    }
    const text = normaliseOfferText(typeof given.text === "string" ? given.text : "");
    const problem = checkOfferText(codePointLength(text), limits);
    return problem === null
      ? { upload: { kind: "text", text } }
      : { error: inputError(problem.code, problem.limit) };
  }

  async #runOffer(
    upload: Upload,
    onProgress: unknown,
    signal: AbortSignal,
  ): Promise<Result<OfferOutcome>> {
    const session = this.#session;
    if (session === null) return failed({ kind: "unavailable", status: "unavailable" });
    const url = `${this.#serviceUrl}/v1/job-offer`;
    const posted = await this.#postWithSession(
      session,
      signal,
      undefined,
      (bearer) => post(url, offerBody(upload), bearer, 200, signal, this.#fetcher),
      undefined,
    );
    if (!posted.ok) return failed(posted.error);

    const progress =
      typeof onProgress === "function" ? (onProgress as (p: Progress) => void) : undefined;
    let report: ReportPayload | null = null;
    let refusal: MessageEvent | null = null;
    let sources: SourceFile[] = [];
    let done: DoneEvent | null = null;
    let errorCode: ErrorCode | null = null;
    const end = await readStream(
      posted.response,
      (event) => {
        if (signal.aborted) return;
        switch (event.event) {
          case "progress":
            this.#call(progress, progressOf(event.data));
            break;
          case "result":
            report = event.data.report;
            break;
          case "message":
            // A refused analysis is a message, never a report (docs/03 §8.3).
            refusal = event.data;
            break;
          case "sources":
            sources = event.data.files;
            break;
          case "error":
            errorCode = event.data.code;
            break;
          case "done":
            done = event.data;
            break;
          default:
            // `delta` is not part of a job-offer stream.
            break;
        }
      },
      signal,
    );
    if (end === "aborted" || signal.aborted) return failed(ABORTED);
    if (isDropped(end)) {
      return failed({ kind: "dropped", reason: end === "invalid" ? "invalid_event" : end });
    }
    const delivered = report as ReportPayload | null;
    const withheld = refusal as MessageEvent | null;
    const last = done as DoneEvent | null;
    const code = errorCode as ErrorCode | null;
    if (code !== null || last === null || last.status === "error") {
      return failed({ kind: "stream", code: code ?? "internal_error" });
    }
    if (withheld !== null) {
      return {
        ok: true,
        value: { kind: "refused", text: withheld.text, sources, turnId: last.turnId },
      };
    }
    if (delivered === null) return failed({ kind: "stream", code: "internal_error" });
    return { ok: true, value: { kind: "report", report: delivered, sources, turnId: last.turnId } };
  }
}

// ─── Helpers and texts ───────────────────────────────────────────────────────

/** Length of a message as the service counts it (code points after normalisation), for a counter. */
export function messageLength(text: string): number {
  try {
    return codePointLength(normaliseVisitorText(typeof text === "string" ? text : ""));
  } catch {
    return 0;
  }
}

/** Length of a pasted job offer as the service counts it, for a counter. */
export function offerTextLength(text: string): number {
  try {
    return offerLength(typeof text === "string" ? text : "");
  } catch {
    return 0;
  }
}

/**
 * The official AI disclosure (docs/06 §10, item 1). Show it permanently wherever the chat is
 * visible, in the page's language: this is your duty (rule 13, D22). You may say more next to it.
 */
export const AI_DISCLOSURE: Readonly<{
  readonly en: "AI assistant. Answers may contain mistakes.";
  readonly fr: "Assistant IA. Les réponses peuvent contenir des erreurs.";
}> = DISCLOSURE;

/**
 * The fixed job-offer disclaimer (docs/09 §6). Every report carries it in `report.disclaimer`;
 * also show it next to the job-offer form (docs/06 §10, item 2).
 */
export const OFFER_DISCLAIMER: Readonly<{ readonly en: string; readonly fr: string }> =
  JOB_OFFER_DISCLAIMERS;

/** The Turnstile action the service expects, for `getToken` implementations: "askfolio_session". */
export const TURNSTILE_ACTION: "askfolio_session" = SESSION_ACTION;
