// Session handling (docs/08-widget.md §5, docs/03-api-contract.md §4): a Turnstile token is
// exchanged for a session token with `POST /v1/sessions`. The session token lives in a private
// field of this object, which writes it nowhere: never in storage, cookies, the DOM or a URL. The
// widget keeps it there only, so a page reload starts over; the headless client persists it in
// `sessionStorage` through `snapshot`, `onChange` and `restore` (D22). Each creation consumes a
// fresh Turnstile token; nothing here retries on its own.
//
// A client module (task 44, the headless client): it imports only other client modules and
// zod-free values of `@askfolio/shared`, and touches no DOM at import time.
import {
  type CreateSessionResponse,
  LIMIT_DEFAULTS,
  SESSION_TOKEN_MAX_CHARS,
  type SessionLimits,
} from "@askfolio/shared";
import { type Failure, isObject, postJson } from "./stream.js";
import type { TokenSource, TurnstileFailureReason } from "./turnstile.js";

/** Client-side limits before a session exists: the shared defaults (S42). */
export const DEFAULT_LIMITS: SessionLimits = Object.freeze({
  messagesPerSession: LIMIT_DEFAULTS.ASKFOLIO_SESSION_MAX_MESSAGES,
  jobOffersPerSession: LIMIT_DEFAULTS.ASKFOLIO_RATE_JOB_OFFER_PER_SESSION,
  maxMessageChars: LIMIT_DEFAULTS.ASKFOLIO_MAX_MESSAGE_CHARS,
  maxTurnsPerConversation: LIMIT_DEFAULTS.ASKFOLIO_MAX_TURNS_PER_CONVERSATION,
  jobOfferMaxPdfBytes: LIMIT_DEFAULTS.ASKFOLIO_PDF_MAX_BYTES,
  jobOfferMaxPdfPages: LIMIT_DEFAULTS.ASKFOLIO_PDF_MAX_PAGES,
  jobOfferMaxTextChars: LIMIT_DEFAULTS.ASKFOLIO_JOB_OFFER_MAX_CHARS,
  jobOfferMinTextChars: LIMIT_DEFAULTS.ASKFOLIO_JOB_OFFER_MIN_CHARS,
});

const LIMIT_KEYS = Object.keys(DEFAULT_LIMITS) as (keyof SessionLimits)[];

/** `{ kind: "turnstile" }`: no Turnstile token, for `reason`, before any request. */
export type SessionFailure = { kind: "turnstile"; reason: TurnstileFailureReason } | Failure;

export type SessionOutcome = { ok: true } | { ok: false; failure: SessionFailure } | "aborted";

/** What a session needs to continue after a page load: its token, expiry and limits. */
export type SessionSnapshot = { token: string; expiresAt: string; limits: SessionLimits };

function freezeLimits(limits: SessionLimits): SessionLimits {
  return Object.freeze(
    Object.fromEntries(LIMIT_KEYS.map((key) => [key, limits[key]])) as SessionLimits,
  );
}

function isSessionResponse(body: unknown): body is CreateSessionResponse {
  if (!isObject(body) || !isObject(body.limits)) return false;
  const limits = body.limits;
  return (
    typeof body.token === "string" &&
    body.token.length > 0 &&
    body.token.length <= SESSION_TOKEN_MAX_CHARS &&
    LIMIT_KEYS.every((key) => {
      const value = limits[key];
      return typeof value === "number" && Number.isInteger(value) && value >= 0;
    })
  );
}

export class Session {
  readonly #url: string;
  readonly #signal: AbortSignal;
  readonly #tokens: TokenSource;
  readonly #fetcher: typeof fetch | undefined;
  #token: string | null = null;
  #expiresAt: string | null = null;
  #limits: SessionLimits = DEFAULT_LIMITS;
  #creating: Promise<SessionOutcome> | null = null;
  /**
   * Called with the new snapshot after a session is created (`null` when its expiry cannot be
   * read, so that it is not persisted), and with `null` after `discard`. Neither `restore` nor
   * `destroy` calls it. The widget sets none.
   */
  onChange: ((snapshot: SessionSnapshot | null) => void) | null = null;

  /**
   * `tokens` gives a fresh Turnstile token per creation (the widget's `TurnstileChallenge`);
   * `fetcher` replaces the global `fetch`, which is otherwise looked up when the request is made.
   */
  constructor(
    serviceUrl: string,
    signal: AbortSignal,
    tokens: TokenSource,
    fetcher?: typeof fetch,
  ) {
    this.#url = `${serviceUrl}/v1/sessions`;
    this.#signal = signal;
    this.#tokens = tokens;
    this.#fetcher = fetcher;
  }

  get ready(): boolean {
    return this.#token !== null;
  }

  get pending(): boolean {
    return this.#creating !== null;
  }

  get limits(): SessionLimits {
    return this.#limits;
  }

  /** `expiresAt` of the session (ISO 8601), or `null` without one or when it cannot be read. */
  get expiresAt(): string | null {
    return this.#expiresAt;
  }

  /** The session, to persist; `null` without one or when its expiry cannot be read. */
  snapshot(): SessionSnapshot | null {
    if (this.#token === null || this.#expiresAt === null) return null;
    return { token: this.#token, expiresAt: this.#expiresAt, limits: this.#limits };
  }

  /**
   * Takes a persisted session back, as checked by the caller, without a request: the service
   * validates the token on the next turn, and a `401` then needs a new session.
   */
  restore(saved: SessionSnapshot): void {
    this.#token = saved.token;
    this.#expiresAt = saved.expiresAt;
    this.#limits = freezeLimits(saved.limits);
  }

  /** The bearer value of a request; `null` without a session. */
  bearer(): string | null {
    return this.#token;
  }

  /**
   * Creates a session, once at a time: concurrent calls share the creation. `watch` receives the
   * `POST /v1/sessions` request, for the waking label.
   */
  create(siteKey: string, watch: (request: Promise<unknown>) => void): Promise<SessionOutcome> {
    if (this.#creating === null) {
      const creating = this.#create(siteKey, watch);
      this.#creating = creating;
      void creating.finally(() => {
        if (this.#creating === creating) this.#creating = null;
      });
    }
    return this.#creating;
  }

  /** Forgets the token (a `401`); the next turn needs a new session. */
  discard(): void {
    this.#token = null;
    this.#expiresAt = null;
    this.onChange?.(null);
  }

  /** Disconnect: drops the token and removes the challenge. */
  destroy(): void {
    this.#token = null;
    this.#expiresAt = null;
    this.#tokens.remove();
  }

  async #create(
    siteKey: string,
    watch: (request: Promise<unknown>) => void,
  ): Promise<SessionOutcome> {
    const turnstileToken = await this.#tokens.token(siteKey, this.#signal);
    if (this.#signal.aborted) return "aborted";
    if (typeof turnstileToken !== "string") {
      return { ok: false, failure: { kind: "turnstile", reason: turnstileToken.reason } };
    }
    const request = postJson(this.#url, { turnstileToken }, null, 201, this.#signal, this.#fetcher);
    watch(request);
    const result = await request;
    if (result === "aborted") return "aborted";
    if (!result.ok) return result;
    let body: unknown;
    try {
      body = await result.value.json();
    } catch {
      body = undefined;
    }
    if (this.#signal.aborted) return "aborted";
    if (!isSessionResponse(body)) {
      return {
        ok: false,
        failure: {
          kind: "http",
          status: result.value.status,
          code: "internal_error",
          retryAfter: null,
        },
      };
    }
    this.#token = body.token;
    // Not checked by the guard, which accepts what the widget always accepted: an unreadable
    // expiry leaves the session usable, and only keeps the client from persisting it.
    const expiresAt: unknown = body.expiresAt;
    this.#expiresAt =
      typeof expiresAt === "string" && !Number.isNaN(Date.parse(expiresAt)) ? expiresAt : null;
    this.#limits = freezeLimits(body.limits);
    this.#tokens.remove();
    this.onChange?.(this.snapshot());
    return { ok: true };
  }
}
