// Server-Sent Events framing (docs/03-api-contract.md §8.1) and the incremental parser used by the
// widget and `askfolio eval`. This module imports nothing, zod included, so the widget bundles the
// parser without the payload schemas of `sse.ts` (docs/08-widget.md §12 size budget).

export const SSE_EVENT_NAMES = [
  "progress",
  "delta",
  "message",
  "sources",
  "result",
  "error",
  "done",
] as const;

// Enumerations of the payloads (docs/03 §8.2); `sse.ts` builds its schemas over them.

/** `progress.stage`. */
export const PROGRESS_STAGES = ["exploring", "writing", "verifying"] as const;
/** `message.mode`. */
export const MESSAGE_MODES = ["streamed", "buffered"] as const;
/** `message.validation`. */
export const MESSAGE_VALIDATIONS = ["not_required", "passed", "rewritten", "refused"] as const;
/** `sources.files[].kind`. */
export const SOURCE_KINDS = ["profile", "index", "card", "file"] as const;
/** `done.status`. */
export const DONE_STATUSES = ["ok", "refused", "error"] as const;

/** First bytes of every stream. */
export const SSE_OPEN_COMMENT = ": open\n\n";
/** Written every `SSE_KEEPALIVE_INTERVAL_MS`. */
export const SSE_KEEPALIVE_COMMENT = ": keepalive\n\n";

/** An event as framed on the wire, before its data is decoded. */
export type RawSseEvent = { event: string; data: string };

type StreamingTextDecoder = { decode(input?: Uint8Array, options?: { stream?: boolean }): string };
type TextDecoderConstructor = new (label?: string) => StreamingTextDecoder;

/**
 * Incremental parser of the `text/event-stream` format (WHATWG HTML, "Parsing an event
 * stream"): accepts chunks split anywhere, including inside a UTF-8 sequence when given bytes,
 * LF, CRLF and CR line endings, and ignores comment lines (`: open`, `: keepalive`) and the
 * `id` and `retry` fields. An event without a `data` field is not dispatched.
 */
export class SseParser {
  #buffer = "";
  #pendingCr = false;
  #started = false;
  #eventName = "";
  #data: string[] = [];
  #decoder: StreamingTextDecoder | undefined;

  /** Feeds one chunk and returns the events it completed, in order. */
  push(chunk: string | Uint8Array): RawSseEvent[] {
    const text = typeof chunk === "string" ? chunk : this.#decode(chunk, true);
    return this.#consume(text);
  }

  /**
   * Ends the stream: flushes the decoder; an event without its blank line is discarded. The
   * parser is then ready for a new stream.
   */
  end(): RawSseEvent[] {
    const events = this.#decoder === undefined ? [] : this.#consume(this.#decode(undefined, false));
    this.#buffer = "";
    this.#pendingCr = false;
    this.#eventName = "";
    this.#data = [];
    // The parser can read a new stream after end(), with its own BOM and decoder state.
    this.#started = false;
    this.#decoder = undefined;
    return events;
  }

  #decode(bytes: Uint8Array | undefined, stream: boolean): string {
    if (this.#decoder === undefined) {
      const Decoder = (globalThis as unknown as { TextDecoder: TextDecoderConstructor })
        .TextDecoder;
      this.#decoder = new Decoder("utf-8");
    }
    return this.#decoder.decode(bytes, { stream });
  }

  #consume(input: string): RawSseEvent[] {
    let text = input;
    if (!this.#started && text.length > 0) {
      this.#started = true;
      if (text.charCodeAt(0) === 0xfeff) text = text.slice(1);
    }
    if (text.length === 0) return [];
    if (this.#pendingCr && text.startsWith("\n")) text = text.slice(1);
    this.#pendingCr = false;

    const events: RawSseEvent[] = [];
    let buffer = this.#buffer + text;
    for (;;) {
      const index = buffer.search(/[\r\n]/);
      if (index === -1) break;
      const line = buffer.slice(0, index);
      if (buffer[index] === "\r") {
        if (index + 1 === buffer.length) {
          // A CR at the end of the chunk may be the first half of a CRLF.
          this.#pendingCr = true;
          buffer = "";
        } else {
          buffer = buffer.slice(index + (buffer[index + 1] === "\n" ? 2 : 1));
        }
      } else {
        buffer = buffer.slice(index + 1);
      }
      const event = this.#line(line);
      if (event !== undefined) events.push(event);
    }
    this.#buffer = buffer;
    return events;
  }

  #line(line: string): RawSseEvent | undefined {
    if (line === "") {
      const data = this.#data;
      const name = this.#eventName;
      this.#data = [];
      this.#eventName = "";
      if (data.length === 0) return undefined;
      return { event: name === "" ? "message" : name, data: data.join("\n") };
    }
    if (line.startsWith(":")) return undefined;
    const colon = line.indexOf(":");
    const field = colon === -1 ? line : line.slice(0, colon);
    let value = colon === -1 ? "" : line.slice(colon + 1);
    if (value.startsWith(" ")) value = value.slice(1);
    if (field === "event") this.#eventName = value;
    else if (field === "data") this.#data.push(value);
    return undefined;
  }
}
