// Cloudflare Turnstile (docs/08-widget.md §6, docs/03-api-contract.md §4.3). The script is loaded
// on first need only, never at page load. The challenge renders into a child element this module
// adds to a parent the caller gives, and removes once done: the widget gives its own element and
// the slot name `turnstile`, so the child (`<div slot="turnstile">`) is projected into the panel
// through a `<slot>` and the third-party iframe behaves as in a normal page.
//
// A client module (task 44, the headless client): it imports only other client modules and
// zod-free values of `@askfolio/shared`, and touches no DOM at import time.
import { TURNSTILE_ACTION, WIDGET_TURNSTILE_LOAD_TIMEOUT_MS } from "@askfolio/shared";

export const TURNSTILE_SCRIPT_URL =
  "https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit";

/** How the challenge looks; each option is passed to Turnstile only when given. */
export type ChallengeAppearance = {
  theme?: "auto" | "light" | "dark";
  size?: "normal" | "flexible" | "compact";
  appearance?: "always" | "interaction-only";
};

export type ChallengeOptions = ChallengeAppearance & {
  /** The `slot` attribute of the child element, for a parent with a shadow root. */
  slot?: string;
};

export type TurnstileRenderOptions = ChallengeAppearance & {
  sitekey: string;
  action: string;
  callback: (token: string) => void;
  "error-callback": () => boolean;
};

/**
 * Why no Turnstile token came: the script did not load (`script`), the challenge failed, expired,
 * was removed or its signal aborted (`challenge`), or there was no parent to render it in
 * (`container`).
 */
export type TurnstileFailureReason = "script" | "challenge" | "container";

export type TokenFailure = { reason: TurnstileFailureReason };

/** What a session needs from Turnstile: a fresh token per attempt, and a way to clean up. */
export type TokenSource = {
  token(siteKey: string, signal: AbortSignal): Promise<string | TokenFailure>;
  remove(): void;
};

/** The part of the Turnstile API the client modules use. */
export type TurnstileApi = {
  render(container: HTMLElement, options: TurnstileRenderOptions): string | null | undefined;
  reset(widgetId: string): void;
  remove(widgetId: string): void;
};

function globalTurnstile(): TurnstileApi | null {
  const candidate = (globalThis as { turnstile?: Partial<TurnstileApi> }).turnstile;
  return candidate !== undefined &&
    typeof candidate.render === "function" &&
    typeof candidate.reset === "function" &&
    typeof candidate.remove === "function"
    ? (candidate as TurnstileApi)
    : null;
}

let loading: Promise<TurnstileApi> | null = null;

/**
 * The Turnstile API: the page's own when it already loaded the script, otherwise from one script
 * element added to `document.head`, shared by every instance while it loads. A failed load is
 * forgotten, so the next call (a visitor's retry) adds a new script.
 */
export function loadTurnstile(doc: Document): Promise<TurnstileApi> {
  const existing = globalTurnstile();
  if (existing !== null) return Promise.resolve(existing);
  if (loading !== null) return loading;
  const attempt = new Promise<TurnstileApi>((resolve, reject) => {
    const script = doc.createElement("script");
    script.src = TURNSTILE_SCRIPT_URL;
    script.async = true;
    const fail = (reason: string): void => {
      clearTimeout(timer);
      script.remove();
      reject(new Error(reason));
    };
    // A script that neither loads nor fails (a stalled network) must not leave Send pending.
    const timer = setTimeout(
      () => fail("turnstile script timed out"),
      WIDGET_TURNSTILE_LOAD_TIMEOUT_MS,
    );
    script.addEventListener("load", () => {
      const api = globalTurnstile();
      if (api === null) fail("turnstile unavailable");
      else {
        clearTimeout(timer);
        resolve(api);
      }
    });
    script.addEventListener("error", () => fail("turnstile script failed to load"));
    doc.head.append(script);
  });
  loading = attempt;
  // Only a load in progress is shared; afterwards the global (or a new script) is used.
  const done = (): void => {
    if (loading === attempt) loading = null;
  };
  attempt.then(done, done);
  return attempt;
}

/**
 * One challenge: renders it on the first `token`, resets it on the next ones, removes it on
 * `remove`. It adds one child element to the parent it is given, and removes only that child. A
 * token is delivered only while one is awaited, so Turnstile's own refreshes never trigger a
 * request.
 */
export class TurnstileChallenge implements TokenSource {
  readonly #parent: () => Element | null;
  readonly #options: ChallengeOptions;
  #container: HTMLElement | null = null;
  #api: TurnstileApi | null = null;
  #widgetId: string | null = null;
  #awaiting: ((outcome: string | TokenFailure) => void) | null = null;
  /** Incremented by `remove`: a `token` call started before it must not render afterwards. */
  #generation = 0;

  constructor(parent: () => Element | null, options: ChallengeOptions = {}) {
    this.#parent = parent;
    this.#options = options;
  }

  /**
   * Resolves to a token, or to the reason none came. A challenge removed, or whose `signal`
   * aborted, while the script loads resolves to `challenge` without rendering.
   */
  async token(siteKey: string, signal: AbortSignal): Promise<string | TokenFailure> {
    this.#awaiting?.({ reason: "challenge" });
    this.#awaiting = null;
    const parent = this.#parent();
    if (parent === null) return { reason: "container" };
    const generation = this.#generation;
    let api: TurnstileApi;
    try {
      api = await loadTurnstile(parent.ownerDocument);
    } catch {
      return { reason: "script" };
    }
    if (generation !== this.#generation || signal.aborted) return { reason: "challenge" };
    this.#api = api;
    return new Promise<string | TokenFailure>((resolve) => {
      const abort = (): void => this.#settle({ reason: "challenge" });
      signal.addEventListener("abort", abort, { once: true });
      this.#awaiting = (outcome) => {
        signal.removeEventListener("abort", abort);
        resolve(outcome);
      };
      try {
        if (this.#widgetId !== null) {
          api.reset(this.#widgetId);
          return;
        }
        const { theme, size, appearance } = this.#options;
        const id = api.render(this.#ensureContainer(parent), {
          sitekey: siteKey,
          action: TURNSTILE_ACTION,
          ...(theme === undefined ? {} : { theme }),
          ...(size === undefined ? {} : { size }),
          ...(appearance === undefined ? {} : { appearance }),
          callback: (token) => this.#settle(token),
          "error-callback": () => {
            this.#settle({ reason: "challenge" });
            return true;
          },
        });
        this.#widgetId = typeof id === "string" ? id : null;
      } catch {
        this.#settle({ reason: "challenge" });
      }
    });
  }

  /** Removes the rendered challenge and the child element; the parent is left as it was. */
  remove(): void {
    this.#generation += 1;
    this.#settle({ reason: "challenge" });
    if (this.#api !== null && this.#widgetId !== null) {
      try {
        this.#api.remove(this.#widgetId);
      } catch {
        // Already gone.
      }
    }
    this.#widgetId = null;
    this.#container?.remove();
    this.#container = null;
  }

  #settle(outcome: string | TokenFailure): void {
    const resolve = this.#awaiting;
    if (resolve === null) return;
    this.#awaiting = null;
    resolve(outcome);
  }

  #ensureContainer(parent: Element): HTMLElement {
    if (this.#container === null || !this.#container.isConnected) {
      const container = parent.ownerDocument.createElement("div");
      if (this.#options.slot !== undefined) container.slot = this.#options.slot;
      parent.append(container);
      this.#container = container;
    }
    return this.#container;
  }
}
